import { kv } from '@vercel/kv'
import type { AppData, Task, WorkLog, CreateTaskInput, UpdateTaskInput, CreateWorkLogInput, TaskStatus } from '@/types'
import { generateId, getCurrentDate, getCurrentTimestamp } from './utils'

const DATA_KEY = 'taskapp:data'

async function getData(): Promise<AppData> {
  const data = await kv.get<AppData>(DATA_KEY)
  return data ?? { tasks: [], workLogs: [] }
}

async function setData(data: AppData): Promise<void> {
  await kv.set(DATA_KEY, data)
}

export async function getTasks(): Promise<Task[]> {
  const data = await getData()
  return data.tasks.filter(task => task.status !== 'archived')
}

export async function getAllTasks(): Promise<Task[]> {
  const data = await getData()
  return data.tasks
}

export async function getArchivedTasks(): Promise<Task[]> {
  const data = await getData()
  return data.tasks.filter(task => task.status === 'archived')
}

export async function getTaskById(id: string): Promise<Task | null> {
  const data = await getData()
  return data.tasks.find(task => task.id === id) ?? null
}

export async function createTask(input: CreateTaskInput): Promise<Task> {
  const data = await getData()
  const status = input.status ?? 'todo'

  const tasksInStatus = data.tasks.filter(t => t.status === status)
  const maxPosition = tasksInStatus.reduce((max, t) => Math.max(max, t.position), -1)

  const now = getCurrentTimestamp()
  const newTask: Task = {
    id: generateId(),
    title: input.title,
    description: input.description ?? '',
    status,
    dueDate: input.dueDate ?? null,
    position: maxPosition + 1,
    createdAt: now,
    updatedAt: now,
  }

  const updatedData: AppData = {
    ...data,
    tasks: [...data.tasks, newTask],
  }
  await setData(updatedData)

  return newTask
}

export async function updateTask(id: string, input: UpdateTaskInput): Promise<Task | null> {
  const data = await getData()
  const taskIndex = data.tasks.findIndex(t => t.id === id)

  if (taskIndex === -1) {
    return null
  }

  const existingTask = data.tasks[taskIndex]
  const updatedTask: Task = {
    ...existingTask,
    ...(input.title !== undefined && { title: input.title }),
    ...(input.description !== undefined && { description: input.description }),
    ...(input.status !== undefined && { status: input.status }),
    ...(input.dueDate !== undefined && { dueDate: input.dueDate }),
    ...(input.position !== undefined && { position: input.position }),
    updatedAt: getCurrentTimestamp(),
  }

  const updatedTasks = [...data.tasks]
  updatedTasks[taskIndex] = updatedTask

  const updatedData: AppData = {
    ...data,
    tasks: updatedTasks,
  }
  await setData(updatedData)

  return updatedTask
}

export async function deleteTask(id: string): Promise<boolean> {
  const data = await getData()
  const taskIndex = data.tasks.findIndex(t => t.id === id)

  if (taskIndex === -1) {
    return false
  }

  const updatedTasks = data.tasks.filter(t => t.id !== id)
  const updatedWorkLogs = data.workLogs.filter(w => w.taskId !== id)

  const updatedData: AppData = {
    tasks: updatedTasks,
    workLogs: updatedWorkLogs,
  }
  await setData(updatedData)

  return true
}

export async function reorderTasks(
  taskId: string,
  newStatus: TaskStatus,
  newPosition: number
): Promise<Task[]> {
  const data = await getData()
  const taskIndex = data.tasks.findIndex(t => t.id === taskId)

  if (taskIndex === -1) {
    return data.tasks
  }

  const task = data.tasks[taskIndex]
  const oldStatus = task.status

  let updatedTasks = [...data.tasks]

  if (oldStatus === newStatus) {
    const tasksInColumn = updatedTasks
      .filter(t => t.status === newStatus && t.id !== taskId)
      .sort((a, b) => a.position - b.position)

    tasksInColumn.splice(newPosition, 0, { ...task, position: newPosition })

    const reorderedTasks = tasksInColumn.map((t, index) => ({
      ...t,
      position: index,
      updatedAt: t.id === taskId ? getCurrentTimestamp() : t.updatedAt,
    }))

    updatedTasks = updatedTasks.map(t => {
      if (t.status !== newStatus) return t
      const reordered = reorderedTasks.find(rt => rt.id === t.id)
      return reordered ?? t
    })
  } else {
    const oldColumnTasks = updatedTasks
      .filter(t => t.status === oldStatus && t.id !== taskId)
      .sort((a, b) => a.position - b.position)
      .map((t, index) => ({ ...t, position: index }))

    const newColumnTasks = updatedTasks
      .filter(t => t.status === newStatus)
      .sort((a, b) => a.position - b.position)

    const movedTask: Task = {
      ...task,
      status: newStatus,
      position: newPosition,
      updatedAt: getCurrentTimestamp(),
    }

    newColumnTasks.splice(newPosition, 0, movedTask)
    const reorderedNewColumn = newColumnTasks.map((t, index) => ({
      ...t,
      position: index,
    }))

    updatedTasks = updatedTasks.map(t => {
      if (t.id === taskId) {
        return reorderedNewColumn.find(rt => rt.id === taskId) ?? t
      }
      if (t.status === oldStatus) {
        return oldColumnTasks.find(oct => oct.id === t.id) ?? t
      }
      if (t.status === newStatus) {
        return reorderedNewColumn.find(rt => rt.id === t.id) ?? t
      }
      return t
    })
  }

  const updatedData: AppData = {
    ...data,
    tasks: updatedTasks,
  }
  await setData(updatedData)

  return updatedTasks
}

export async function getWorkLogs(date?: string): Promise<WorkLog[]> {
  const data = await getData()
  if (date) {
    return data.workLogs.filter(w => w.date === date)
  }
  return data.workLogs
}

export async function getWorkLogsByTaskId(taskId: string): Promise<WorkLog[]> {
  const data = await getData()
  return data.workLogs.filter(w => w.taskId === taskId)
}

export async function createWorkLog(input: CreateWorkLogInput): Promise<WorkLog> {
  const data = await getData()

  const newWorkLog: WorkLog = {
    id: generateId(),
    taskId: input.taskId,
    content: input.content,
    date: input.date ?? getCurrentDate(),
    createdAt: getCurrentTimestamp(),
  }

  const updatedData: AppData = {
    ...data,
    workLogs: [...data.workLogs, newWorkLog],
  }
  await setData(updatedData)

  return newWorkLog
}

export async function deleteWorkLog(id: string): Promise<boolean> {
  const data = await getData()
  const workLogIndex = data.workLogs.findIndex(w => w.id === id)

  if (workLogIndex === -1) {
    return false
  }

  const updatedWorkLogs = data.workLogs.filter(w => w.id !== id)

  const updatedData: AppData = {
    ...data,
    workLogs: updatedWorkLogs,
  }
  await setData(updatedData)

  return true
}

