'use client'

import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import type { Task, WorkLog } from '@/types'
import { cn, isOverdue, formatDate } from '@/lib/utils'

interface TaskCardProps {
  task: Task
  latestWorkLog?: WorkLog
  onClick: () => void
}

export function TaskCard({ task, latestWorkLog, onClick }: TaskCardProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: task.id })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  }

  const overdue = isOverdue(task.dueDate)

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      onClick={onClick}
      className={cn(
        'task-card bg-white rounded-lg shadow-sm border p-4 mb-3 hover:shadow-md transition-shadow',
        isDragging && 'task-card-dragging shadow-lg',
        overdue && 'border-red-400 border-2'
      )}
    >
      <h3 className="font-medium text-gray-900 mb-2 line-clamp-2">
        {task.title}
      </h3>
      {task.dueDate && (
        <p
          className={cn(
            'text-xs mb-2',
            overdue ? 'text-red-600 font-medium' : 'text-gray-500'
          )}
        >
          Due: {formatDate(task.dueDate)}
        </p>
      )}
      {latestWorkLog && (
        <p className="text-xs text-gray-400 line-clamp-1">
          {latestWorkLog.content}
        </p>
      )}
    </div>
  )
}

