'use client'

import { useDroppable } from '@dnd-kit/core'
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable'
import type { Task, WorkLog, TaskStatus } from '@/types'
import { TaskCard } from './TaskCard'
import { cn } from '@/lib/utils'

interface KanbanColumnProps {
  status: TaskStatus
  title: string
  tasks: Task[]
  workLogs: WorkLog[]
  onTaskClick: (task: Task) => void
  onAddTask: () => void
}

const columnColors: Record<TaskStatus, string> = {
  todo: 'bg-gray-50 border-gray-200',
  doing: 'bg-blue-50 border-blue-200',
  done: 'bg-green-50 border-green-200',
  archived: 'bg-gray-100 border-gray-300',
}

const headerColors: Record<TaskStatus, string> = {
  todo: 'text-gray-700',
  doing: 'text-blue-700',
  done: 'text-green-700',
  archived: 'text-gray-600',
}

export function KanbanColumn({
  status,
  title,
  tasks,
  workLogs,
  onTaskClick,
  onAddTask,
}: KanbanColumnProps) {
  const { setNodeRef, isOver } = useDroppable({ id: status })

  const sortedTasks = [...tasks].sort((a, b) => a.position - b.position)
  const taskIds = sortedTasks.map((t) => t.id)

  const getLatestWorkLog = (taskId: string): WorkLog | undefined => {
    const taskLogs = workLogs
      .filter((w) => w.taskId === taskId)
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
    return taskLogs[0]
  }

  return (
    <div
      ref={setNodeRef}
      className={cn(
        'kanban-column flex-1 min-w-[280px] max-w-[350px] rounded-lg border-2 p-4 transition-colors',
        columnColors[status],
        isOver && 'border-blue-400 bg-blue-100'
      )}
    >
      <div className="flex justify-between items-center mb-4">
        <h2 className={cn('font-semibold text-lg', headerColors[status])}>
          {title}
          <span className="ml-2 text-sm font-normal text-gray-500">
            ({tasks.length})
          </span>
        </h2>
        {status !== 'archived' && (
          <button
            onClick={onAddTask}
            className="text-gray-400 hover:text-gray-600 text-xl leading-none transition-colors"
            title="Add task"
          >
            +
          </button>
        )}
      </div>
      <SortableContext items={taskIds} strategy={verticalListSortingStrategy}>
        <div className="space-y-0">
          {sortedTasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              latestWorkLog={getLatestWorkLog(task.id)}
              onClick={() => onTaskClick(task)}
            />
          ))}
        </div>
      </SortableContext>
      {tasks.length === 0 && (
        <p className="text-gray-400 text-sm text-center py-8">No tasks</p>
      )}
    </div>
  )
}

