'use client'

import { useState, useMemo } from 'react'
import {
  startOfWeek,
  endOfWeek,
  addWeeks,
  subWeeks,
  format,
  eachDayOfInterval,
  isSameDay,
  parseISO,
} from 'date-fns'
import type { WorkLog, Task } from '@/types'
import { cn } from '@/lib/utils'

interface WeeklyViewProps {
  workLogs: WorkLog[]
  tasks: Task[]
}

export function WeeklyView({ workLogs, tasks }: WeeklyViewProps) {
  const [currentWeekStart, setCurrentWeekStart] = useState(() =>
    startOfWeek(new Date(), { weekStartsOn: 1 })
  )

  const weekEnd = endOfWeek(currentWeekStart, { weekStartsOn: 1 })

  const daysOfWeek = useMemo(
    () => eachDayOfInterval({ start: currentWeekStart, end: weekEnd }),
    [currentWeekStart, weekEnd]
  )

  const taskMap = useMemo(() => {
    const map = new Map<string, Task>()
    tasks.forEach((task) => map.set(task.id, task))
    return map
  }, [tasks])

  const weeklyLogs = useMemo(() => {
    return workLogs.filter((log) => {
      const logDate = parseISO(log.date)
      return logDate >= currentWeekStart && logDate <= weekEnd
    })
  }, [workLogs, currentWeekStart, weekEnd])

  const logsByDay = useMemo(() => {
    const map = new Map<string, WorkLog[]>()
    daysOfWeek.forEach((day) => {
      const dayStr = format(day, 'yyyy-MM-dd')
      map.set(dayStr, [])
    })
    weeklyLogs.forEach((log) => {
      const existing = map.get(log.date) ?? []
      map.set(log.date, [...existing, log])
    })
    return map
  }, [weeklyLogs, daysOfWeek])

  const stats = useMemo(() => {
    const completedTaskIds = new Set<string>()
    const inProgressTaskIds = new Set<string>()

    weeklyLogs.forEach((log) => {
      const task = taskMap.get(log.taskId)
      if (task) {
        if (task.status === 'done' || task.status === 'archived') {
          completedTaskIds.add(task.id)
        } else if (task.status === 'doing') {
          inProgressTaskIds.add(task.id)
        }
      }
    })

    return {
      logCount: weeklyLogs.length,
      completedTasks: completedTaskIds.size,
      inProgressTasks: inProgressTaskIds.size,
    }
  }, [weeklyLogs, taskMap])

  const goToPreviousWeek = () => setCurrentWeekStart((prev) => subWeeks(prev, 1))
  const goToNextWeek = () => setCurrentWeekStart((prev) => addWeeks(prev, 1))
  const goToCurrentWeek = () =>
    setCurrentWeekStart(startOfWeek(new Date(), { weekStartsOn: 1 }))

  const isToday = (day: Date) => isSameDay(day, new Date())

  return (
    <div>
      <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div className="flex items-center gap-4">
            <button
              onClick={goToPreviousWeek}
              className="p-2 hover:bg-gray-100 rounded-md transition-colors"
            >
              ←
            </button>
            <div className="text-center">
              <h2 className="font-semibold text-gray-900">
                {format(currentWeekStart, 'MMM d')} - {format(weekEnd, 'MMM d, yyyy')}
              </h2>
            </div>
            <button
              onClick={goToNextWeek}
              className="p-2 hover:bg-gray-100 rounded-md transition-colors"
            >
              →
            </button>
            <button
              onClick={goToCurrentWeek}
              className="text-sm text-blue-600 hover:text-blue-700"
            >
              Today
            </button>
          </div>
          <div className="flex gap-6 text-sm">
            <div className="text-center">
              <p className="text-2xl font-bold text-gray-900">{stats.logCount}</p>
              <p className="text-gray-500">Work Logs</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-green-600">{stats.completedTasks}</p>
              <p className="text-gray-500">Completed</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-blue-600">{stats.inProgressTasks}</p>
              <p className="text-gray-500">In Progress</p>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-7 gap-4">
        {daysOfWeek.map((day) => {
          const dayStr = format(day, 'yyyy-MM-dd')
          const logs = logsByDay.get(dayStr) ?? []
          const dayName = format(day, 'EEE')
          const dayNum = format(day, 'd')

          return (
            <div
              key={dayStr}
              className={cn(
                'bg-white rounded-lg shadow-sm overflow-hidden',
                isToday(day) && 'ring-2 ring-blue-500'
              )}
            >
              <div
                className={cn(
                  'px-3 py-2 border-b',
                  isToday(day) ? 'bg-blue-50' : 'bg-gray-50'
                )}
              >
                <p className="text-xs text-gray-500">{dayName}</p>
                <p
                  className={cn(
                    'text-lg font-semibold',
                    isToday(day) ? 'text-blue-600' : 'text-gray-900'
                  )}
                >
                  {dayNum}
                </p>
              </div>
              <div className="p-2 min-h-[120px] max-h-[200px] overflow-y-auto">
                {logs.length === 0 ? (
                  <p className="text-xs text-gray-400 text-center py-4">
                    No logs
                  </p>
                ) : (
                  <div className="space-y-2">
                    {logs.map((log) => {
                      const task = taskMap.get(log.taskId)
                      return (
                        <div
                          key={log.id}
                          className="p-2 bg-gray-50 rounded text-xs"
                        >
                          <p className="text-gray-900 line-clamp-2">
                            {log.content}
                          </p>
                          {task && (
                            <p className="text-gray-500 mt-1 truncate">
                              {task.title}
                            </p>
                          )}
                        </div>
                      )
                    })}
                  </div>
                )}
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

