import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getWorkLogs, createWorkLog } from '@/lib/kv'

const createWorkLogSchema = z.object({
  taskId: z.string().min(1),
  content: z.string().min(1, 'Content is required'),
  date: z.string().optional(),
})

export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url)
    const date = searchParams.get('date') ?? undefined

    const workLogs = await getWorkLogs(date)
    return NextResponse.json({ success: true, data: workLogs })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to fetch work logs'
    return NextResponse.json(
      { success: false, error: message },
      { status: 500 }
    )
  }
}

export async function POST(request: Request) {
  try {
    const body = await request.json()
    const parsed = createWorkLogSchema.safeParse(body)

    if (!parsed.success) {
      return NextResponse.json(
        { success: false, error: 'Invalid request', details: parsed.error.errors },
        { status: 400 }
      )
    }

    const workLog = await createWorkLog(parsed.data)
    return NextResponse.json({ success: true, data: workLog }, { status: 201 })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to create work log'
    return NextResponse.json(
      { success: false, error: message },
      { status: 500 }
    )
  }
}

