'use client'

import { useState, useEffect } from 'react'
import type { Task, WorkLog, TaskStatus } from '@/types'
import { formatDate, formatDateTime, cn } from '@/lib/utils'

interface TaskModalProps {
  task: Task
  workLogs: WorkLog[]
  isOpen: boolean
  onClose: () => void
  onUpdate: (updates: Partial<Task>) => Promise<void>
  onDelete: () => Promise<void>
  onArchive: () => Promise<void>
  onAddWorkLog: (content: string) => Promise<void>
  onDeleteWorkLog: (id: string) => Promise<void>
}

const statusLabels: Record<TaskStatus, string> = {
  todo: 'Todo',
  doing: 'Doing',
  done: 'Done',
  archived: 'Archived',
}

const statusColors: Record<TaskStatus, string> = {
  todo: 'bg-gray-200 text-gray-700',
  doing: 'bg-blue-200 text-blue-700',
  done: 'bg-green-200 text-green-700',
  archived: 'bg-gray-300 text-gray-600',
}

export function TaskModal({
  task,
  workLogs,
  isOpen,
  onClose,
  onUpdate,
  onDelete,
  onArchive,
  onAddWorkLog,
  onDeleteWorkLog,
}: TaskModalProps) {
  const [title, setTitle] = useState(task.title)
  const [description, setDescription] = useState(task.description)
  const [dueDate, setDueDate] = useState(task.dueDate ?? '')
  const [newWorkLogContent, setNewWorkLogContent] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)

  useEffect(() => {
    setTitle(task.title)
    setDescription(task.description)
    setDueDate(task.dueDate ?? '')
  }, [task])

  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    if (isOpen) {
      document.addEventListener('keydown', handleEscape)
      document.body.style.overflow = 'hidden'
    }
    return () => {
      document.removeEventListener('keydown', handleEscape)
      document.body.style.overflow = ''
    }
  }, [isOpen, onClose])

  if (!isOpen) return null

  const handleSave = async () => {
    setIsSubmitting(true)
    try {
      await onUpdate({
        title,
        description,
        dueDate: dueDate || null,
      })
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleStatusChange = async (newStatus: TaskStatus) => {
    setIsSubmitting(true)
    try {
      await onUpdate({ status: newStatus })
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleAddWorkLog = async () => {
    if (!newWorkLogContent.trim()) return
    setIsSubmitting(true)
    try {
      await onAddWorkLog(newWorkLogContent)
      setNewWorkLogContent('')
    } finally {
      setIsSubmitting(false)
    }
  }

  const sortedWorkLogs = [...workLogs].sort(
    (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  )

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div
        className="absolute inset-0 bg-black/50"
        onClick={onClose}
      />
      <div className="relative bg-white rounded-lg shadow-xl w-full max-w-2xl max-h-[90vh] overflow-hidden mx-4">
        <div className="p-6 overflow-y-auto max-h-[90vh]">
          <div className="flex justify-between items-start mb-4">
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              onBlur={handleSave}
              className="text-xl font-bold text-gray-900 w-full border-0 border-b-2 border-transparent focus:border-blue-500 focus:outline-none"
            />
            <button
              onClick={onClose}
              className="ml-4 text-gray-400 hover:text-gray-600 text-2xl leading-none"
            >
              ×
            </button>
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Status
            </label>
            <div className="flex flex-wrap gap-2">
              {(['todo', 'doing', 'done'] as TaskStatus[]).map((status) => (
                <button
                  key={status}
                  onClick={() => handleStatusChange(status)}
                  disabled={isSubmitting}
                  className={cn(
                    'px-3 py-1 rounded-full text-sm font-medium transition-colors',
                    task.status === status
                      ? statusColors[status]
                      : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                  )}
                >
                  {statusLabels[status]}
                </button>
              ))}
            </div>
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Due Date
            </label>
            <input
              type="date"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
              onBlur={handleSave}
              className="px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            {dueDate && (
              <button
                onClick={() => {
                  setDueDate('')
                  onUpdate({ dueDate: null })
                }}
                className="ml-2 text-sm text-gray-500 hover:text-gray-700"
              >
                Clear
              </button>
            )}
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Description
            </label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              onBlur={handleSave}
              rows={4}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
              placeholder="Add a description..."
            />
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Work Logs
            </label>
            <div className="flex gap-2 mb-4">
              <input
                type="text"
                value={newWorkLogContent}
                onChange={(e) => setNewWorkLogContent(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAddWorkLog()}
                className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                placeholder="Add work log..."
              />
              <button
                onClick={handleAddWorkLog}
                disabled={isSubmitting || !newWorkLogContent.trim()}
                className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Add
              </button>
            </div>
            <div className="space-y-3 max-h-48 overflow-y-auto">
              {sortedWorkLogs.map((log) => (
                <div
                  key={log.id}
                  className="flex justify-between items-start p-3 bg-gray-50 rounded-md"
                >
                  <div className="flex-1">
                    <p className="text-sm text-gray-900">{log.content}</p>
                    <p className="text-xs text-gray-500 mt-1">
                      {formatDate(log.date)} - {formatDateTime(log.createdAt)}
                    </p>
                  </div>
                  <button
                    onClick={() => onDeleteWorkLog(log.id)}
                    className="ml-2 text-gray-400 hover:text-red-500"
                  >
                    ×
                  </button>
                </div>
              ))}
              {sortedWorkLogs.length === 0 && (
                <p className="text-sm text-gray-400 text-center py-4">
                  No work logs yet
                </p>
              )}
            </div>
          </div>

          <div className="flex justify-between pt-4 border-t border-gray-200">
            <div className="flex gap-2">
              {task.status === 'done' && (
                <button
                  onClick={onArchive}
                  disabled={isSubmitting}
                  className="px-4 py-2 bg-gray-600 text-white rounded-md hover:bg-gray-700 disabled:opacity-50"
                >
                  Archive
                </button>
              )}
            </div>
            <button
              onClick={onDelete}
              disabled={isSubmitting}
              className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 disabled:opacity-50"
            >
              Delete
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

