'use client'

import { useState, useMemo } from 'react'
import type { WorkLog, Task } from '@/types'
import { formatDate, formatDateTime } from '@/lib/utils'

interface DailyViewProps {
  workLogs: WorkLog[]
  tasks: Task[]
}

export function DailyView({ workLogs, tasks }: DailyViewProps) {
  const [filterDate, setFilterDate] = useState('')

  const taskMap = useMemo(() => {
    const map = new Map<string, Task>()
    tasks.forEach((task) => map.set(task.id, task))
    return map
  }, [tasks])

  const groupedLogs = useMemo(() => {
    const filtered = filterDate
      ? workLogs.filter((log) => log.date === filterDate)
      : workLogs

    const groups = new Map<string, WorkLog[]>()

    filtered.forEach((log) => {
      const existing = groups.get(log.date) ?? []
      groups.set(log.date, [...existing, log])
    })

    return Array.from(groups.entries())
      .sort(([a], [b]) => b.localeCompare(a))
      .map(([date, logs]) => ({
        date,
        logs: logs.sort(
          (a, b) =>
            new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        ),
      }))
  }, [workLogs, filterDate])

  return (
    <div>
      <div className="mb-6 flex items-center gap-4">
        <label className="text-sm font-medium text-gray-700">
          Filter by date:
        </label>
        <input
          type="date"
          value={filterDate}
          onChange={(e) => setFilterDate(e.target.value)}
          className="px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
        {filterDate && (
          <button
            onClick={() => setFilterDate('')}
            className="text-sm text-gray-500 hover:text-gray-700"
          >
            Clear filter
          </button>
        )}
      </div>

      {groupedLogs.length === 0 ? (
        <div className="bg-white rounded-lg shadow-sm p-8 text-center">
          <p className="text-gray-500">No work logs found</p>
        </div>
      ) : (
        <div className="space-y-6">
          {groupedLogs.map(({ date, logs }) => (
            <div key={date} className="bg-white rounded-lg shadow-sm overflow-hidden">
              <div className="bg-gray-50 px-6 py-3 border-b border-gray-200">
                <h2 className="font-semibold text-gray-900">
                  {formatDate(date)}
                </h2>
                <p className="text-sm text-gray-500">{logs.length} entries</p>
              </div>
              <div className="divide-y divide-gray-100">
                {logs.map((log) => {
                  const task = taskMap.get(log.taskId)
                  return (
                    <div key={log.id} className="px-6 py-4">
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <p className="text-gray-900">{log.content}</p>
                          <div className="mt-1 flex items-center gap-2 text-sm text-gray-500">
                            {task && (
                              <>
                                <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-gray-100 text-gray-700">
                                  {task.title}
                                </span>
                                {task.status === 'archived' && (
                                  <span className="text-xs text-gray-400">
                                    (archived)
                                  </span>
                                )}
                              </>
                            )}
                          </div>
                        </div>
                        <span className="text-xs text-gray-400 ml-4 whitespace-nowrap">
                          {formatDateTime(log.createdAt)}
                        </span>
                      </div>
                    </div>
                  )
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

