'use client'

import { useState, useMemo } from 'react'
import type { Task, WorkLog } from '@/types'
import { formatDate, formatDateTime } from '@/lib/utils'

interface ArchiveViewProps {
  initialTasks: Task[]
  workLogs: WorkLog[]
}

export function ArchiveView({ initialTasks, workLogs }: ArchiveViewProps) {
  const [tasks, setTasks] = useState(initialTasks)
  const [isProcessing, setIsProcessing] = useState<string | null>(null)

  const taskWorkLogs = useMemo(() => {
    const map = new Map<string, WorkLog[]>()
    workLogs.forEach((log) => {
      const existing = map.get(log.taskId) ?? []
      map.set(log.taskId, [...existing, log])
    })
    return map
  }, [workLogs])

  const sortedTasks = useMemo(
    () =>
      [...tasks].sort(
        (a, b) =>
          new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
      ),
    [tasks]
  )

  const handleRestore = async (taskId: string) => {
    setIsProcessing(taskId)
    try {
      const response = await fetch(`/api/tasks/${taskId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'todo' }),
      })

      if (response.ok) {
        setTasks((prev) => prev.filter((t) => t.id !== taskId))
      }
    } finally {
      setIsProcessing(null)
    }
  }

  const handleDelete = async (taskId: string) => {
    if (!confirm('Are you sure you want to permanently delete this task?')) {
      return
    }

    setIsProcessing(taskId)
    try {
      const response = await fetch(`/api/tasks/${taskId}`, {
        method: 'DELETE',
      })

      if (response.ok) {
        setTasks((prev) => prev.filter((t) => t.id !== taskId))
      }
    } finally {
      setIsProcessing(null)
    }
  }

  if (sortedTasks.length === 0) {
    return (
      <div className="bg-white rounded-lg shadow-sm p-8 text-center">
        <p className="text-gray-500">No archived tasks</p>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {sortedTasks.map((task) => {
        const logs = taskWorkLogs.get(task.id) ?? []
        const isLoading = isProcessing === task.id

        return (
          <div
            key={task.id}
            className="bg-white rounded-lg shadow-sm overflow-hidden"
          >
            <div className="p-4 border-b border-gray-100">
              <div className="flex justify-between items-start">
                <div className="flex-1">
                  <h3 className="font-medium text-gray-900">{task.title}</h3>
                  {task.description && (
                    <p className="text-sm text-gray-600 mt-1">
                      {task.description}
                    </p>
                  )}
                  <div className="flex items-center gap-4 mt-2 text-xs text-gray-500">
                    {task.dueDate && (
                      <span>Due: {formatDate(task.dueDate)}</span>
                    )}
                    <span>Archived: {formatDateTime(task.updatedAt)}</span>
                    <span>{logs.length} work logs</span>
                  </div>
                </div>
                <div className="flex gap-2 ml-4">
                  <button
                    onClick={() => handleRestore(task.id)}
                    disabled={isLoading}
                    className="px-3 py-1 text-sm bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50"
                  >
                    Restore
                  </button>
                  <button
                    onClick={() => handleDelete(task.id)}
                    disabled={isLoading}
                    className="px-3 py-1 text-sm bg-red-600 text-white rounded hover:bg-red-700 disabled:opacity-50"
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
            {logs.length > 0 && (
              <div className="px-4 py-3 bg-gray-50">
                <p className="text-xs text-gray-500 mb-2">Work Logs:</p>
                <div className="space-y-1 max-h-32 overflow-y-auto">
                  {logs
                    .sort(
                      (a, b) =>
                        new Date(b.createdAt).getTime() -
                        new Date(a.createdAt).getTime()
                    )
                    .slice(0, 5)
                    .map((log) => (
                      <div key={log.id} className="text-xs text-gray-600">
                        <span className="text-gray-400 mr-2">
                          {formatDate(log.date)}
                        </span>
                        {log.content}
                      </div>
                    ))}
                  {logs.length > 5 && (
                    <p className="text-xs text-gray-400">
                      + {logs.length - 5} more logs
                    </p>
                  )}
                </div>
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}

