'use client'

import { useState, useCallback } from 'react'
import {
  DndContext,
  DragOverlay,
  closestCorners,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  type DragStartEvent,
  type DragEndEvent,
} from '@dnd-kit/core'
import { sortableKeyboardCoordinates } from '@dnd-kit/sortable'
import type { Task, WorkLog, TaskStatus } from '@/types'
import { KanbanColumn } from './KanbanColumn'
import { TaskCard } from './TaskCard'
import { TaskModal } from './TaskModal'
import { AddTaskModal } from './AddTaskModal'

interface KanbanBoardProps {
  initialTasks: Task[]
  initialWorkLogs: WorkLog[]
}

const columns: { status: TaskStatus; title: string }[] = [
  { status: 'todo', title: '未着手' },
  { status: 'doing', title: '進行中' },
  { status: 'done', title: '完了' },
]

export function KanbanBoard({ initialTasks, initialWorkLogs }: KanbanBoardProps) {
  const [tasks, setTasks] = useState<Task[]>(initialTasks)
  const [workLogs, setWorkLogs] = useState<WorkLog[]>(initialWorkLogs)
  const [activeTask, setActiveTask] = useState<Task | null>(null)
  const [selectedTask, setSelectedTask] = useState<Task | null>(null)
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false)
  const [isAddModalOpen, setIsAddModalOpen] = useState(false)
  const [addTaskStatus, setAddTaskStatus] = useState<TaskStatus>('todo')

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  )

  const getTasksByStatus = (status: TaskStatus) =>
    tasks.filter((task) => task.status === status)

  const handleDragStart = (event: DragStartEvent) => {
    const task = tasks.find((t) => t.id === event.active.id)
    if (task) {
      setActiveTask(task)
    }
  }

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event
    setActiveTask(null)

    if (!over) return

    const activeId = active.id as string
    const overId = over.id as string

    const activeTaskData = tasks.find((t) => t.id === activeId)
    if (!activeTaskData) return

    let newStatus: TaskStatus
    let newPosition: number

    const overTask = tasks.find((t) => t.id === overId)
    if (overTask) {
      newStatus = overTask.status
      const tasksInColumn = tasks.filter((t) => t.status === newStatus)
      const overIndex = tasksInColumn.findIndex((t) => t.id === overId)
      newPosition = overIndex
    } else {
      newStatus = overId as TaskStatus
      const tasksInColumn = tasks.filter((t) => t.status === newStatus)
      newPosition = tasksInColumn.length
    }

    if (activeTaskData.status === newStatus) {
      const tasksInColumn = tasks
        .filter((t) => t.status === newStatus)
        .sort((a, b) => a.position - b.position)
      const oldIndex = tasksInColumn.findIndex((t) => t.id === activeId)
      if (oldIndex === newPosition) return
    }

    const updatedTasks = tasks.map((t) => {
      if (t.id === activeId) {
        return { ...t, status: newStatus, position: newPosition }
      }
      return t
    })
    setTasks(updatedTasks)

    try {
      const response = await fetch('/api/tasks/reorder', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          taskId: activeId,
          newStatus,
          newPosition,
        }),
      })

      if (response.ok) {
        const data = await response.json()
        if (data.success) {
          setTasks(data.data)
        }
      }
    } catch {
      setTasks(initialTasks)
    }
  }

  const handleTaskClick = useCallback((task: Task) => {
    setSelectedTask(task)
    setIsTaskModalOpen(true)
  }, [])

  const handleAddTaskClick = useCallback((status: TaskStatus) => {
    setAddTaskStatus(status)
    setIsAddModalOpen(true)
  }, [])

  const handleAddTask = async (title: string, status: TaskStatus) => {
    const response = await fetch('/api/tasks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title, status }),
    })

    if (response.ok) {
      const data = await response.json()
      if (data.success) {
        setTasks((prev) => [...prev, data.data])
      }
    }
  }

  const handleUpdateTask = async (updates: Partial<Task>) => {
    if (!selectedTask) return

    const response = await fetch(`/api/tasks/${selectedTask.id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(updates),
    })

    if (response.ok) {
      const data = await response.json()
      if (data.success) {
        setTasks((prev) =>
          prev.map((t) => (t.id === selectedTask.id ? data.data : t))
        )
        setSelectedTask(data.data)
      }
    }
  }

  const handleDeleteTask = async () => {
    if (!selectedTask) return

    const response = await fetch(`/api/tasks/${selectedTask.id}`, {
      method: 'DELETE',
    })

    if (response.ok) {
      setTasks((prev) => prev.filter((t) => t.id !== selectedTask.id))
      setWorkLogs((prev) => prev.filter((w) => w.taskId !== selectedTask.id))
      setIsTaskModalOpen(false)
      setSelectedTask(null)
    }
  }

  const handleArchiveTask = async () => {
    if (!selectedTask) return
    await handleUpdateTask({ status: 'archived' })
    setIsTaskModalOpen(false)
    setSelectedTask(null)
  }

  const handleAddWorkLog = async (content: string) => {
    if (!selectedTask) return

    const response = await fetch('/api/worklogs', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        taskId: selectedTask.id,
        content,
      }),
    })

    if (response.ok) {
      const data = await response.json()
      if (data.success) {
        setWorkLogs((prev) => [...prev, data.data])
      }
    }
  }

  const handleDeleteWorkLog = async (id: string) => {
    const response = await fetch(`/api/worklogs/${id}`, {
      method: 'DELETE',
    })

    if (response.ok) {
      setWorkLogs((prev) => prev.filter((w) => w.id !== id))
    }
  }

  const selectedTaskWorkLogs = selectedTask
    ? workLogs.filter((w) => w.taskId === selectedTask.id)
    : []

  return (
    <>
      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="flex gap-4 overflow-x-auto pb-4">
          {columns.map(({ status, title }) => (
            <KanbanColumn
              key={status}
              status={status}
              title={title}
              tasks={getTasksByStatus(status)}
              workLogs={workLogs}
              onTaskClick={handleTaskClick}
              onAddTask={() => handleAddTaskClick(status)}
            />
          ))}
        </div>
        <DragOverlay>
          {activeTask && (
            <div className="opacity-80">
              <TaskCard
                task={activeTask}
                onClick={() => {}}
              />
            </div>
          )}
        </DragOverlay>
      </DndContext>

      {selectedTask && (
        <TaskModal
          task={selectedTask}
          workLogs={selectedTaskWorkLogs}
          isOpen={isTaskModalOpen}
          onClose={() => {
            setIsTaskModalOpen(false)
            setSelectedTask(null)
          }}
          onUpdate={handleUpdateTask}
          onDelete={handleDeleteTask}
          onArchive={handleArchiveTask}
          onAddWorkLog={handleAddWorkLog}
          onDeleteWorkLog={handleDeleteWorkLog}
        />
      )}

      <AddTaskModal
        isOpen={isAddModalOpen}
        initialStatus={addTaskStatus}
        onClose={() => setIsAddModalOpen(false)}
        onSubmit={handleAddTask}
      />
    </>
  )
}

