            />
            {dueDate && (
              <button
                onClick={() => {
                  setDueDate('')
                  onUpdate({ dueDate: null })
                }}
                className="ml-2 text-sm text-[var(--wa-text-muted)] hover:text-[var(--wa-text-primary)]"
              >
                解除
              </button>
            )}
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-[var(--wa-text-secondary)] mb-2">
              詳細
            </label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              onBlur={handleSave}
              rows={4}
              className="w-full px-3 py-2 border border-[var(--wa-border)] rounded-sm focus:outline-none focus:ring-2 focus:ring-[var(--wa-primary-light)] resize-none bg-[var(--wa-surface)]"
              placeholder="詳細を入力..."
            />
          </div>

