                value={newWorkLogContent}
                onChange={(e) => setNewWorkLogContent(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAddWorkLog()}
                className="flex-1 px-3 py-2 border border-[var(--wa-border)] rounded-sm focus:outline-none focus:ring-2 focus:ring-[var(--wa-primary-light)] bg-[var(--wa-surface)]"
                placeholder="作業記録を追加..."
              />
              <button
                onClick={handleAddWorkLog}
                disabled={isSubmitting || !newWorkLogContent.trim()}
                className="px-4 py-2 bg-[var(--wa-primary)] text-white rounded-sm hover:bg-[var(--wa-primary-dark)] disabled:opacity-50 disabled:cursor-not-allowed"
              >
                追加
              </button>
            </div>
            <div className="space-y-3 max-h-48 overflow-y-auto">
              {sortedWorkLogs.map((log) => (
                <div
                  key={log.id}
                  className="flex justify-between items-start p-3 bg-[var(--wa-surface-alt)] rounded-sm"
                >
                  <div className="flex-1">
                    <p className="text-sm text-[var(--wa-text-primary)]">{log.content}</p>
                    <p className="text-xs text-[var(--wa-text-muted)] mt-1">
                      {formatDate(log.date)} - {formatDateTime(log.createdAt)}
                    </p>
                  </div>
                  <button
                    onClick={() => onDeleteWorkLog(log.id)}
                    className="ml-2 text-[var(--wa-text-muted)] hover:text-[var(--wa-secondary)]"
                  >
                    ×
                  </button>
                </div>
              ))}
              {sortedWorkLogs.length === 0 && (
                <p className="text-sm text-[var(--wa-text-muted)] text-center py-4">
                  作業記録はありません
                </p>
              )}
            </div>
          </div>

          <div className="flex justify-between pt-4 border-t border-[var(--wa-border)]">
            <div className="flex gap-2">
              {task.status === 'done' && (
                <button
                  onClick={onArchive}
                  disabled={isSubmitting}
                  className="px-4 py-2 bg-[var(--wa-border-dark)] text-white rounded-sm hover:bg-[var(--wa-text-secondary)] disabled:opacity-50"
                >
                  保管
                </button>
              )}
            </div>
            <button
              onClick={onDelete}
              disabled={isSubmitting}
              className="px-4 py-2 bg-[var(--wa-secondary)] text-white rounded-sm hover:bg-[var(--wa-secondary-light)] disabled:opacity-50"
            >
              削除
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

