            <div className="flex gap-2">
              {task.status === 'done' && (
                <button
                  onClick={onArchive}
                  disabled={isSubmitting}
                  className="px-4 py-2 bg-[var(--wa-border-dark)] text-white rounded-sm hover:bg-[var(--wa-text-secondary)] disabled:opacity-50"
                >
                  保管
                </button>
              )}
            </div>
            <button
              onClick={onDelete}
              disabled={isSubmitting}
              className="px-4 py-2 bg-[var(--wa-secondary)] text-white rounded-sm hover:bg-[var(--wa-secondary-light)] disabled:opacity-50"
            >
              削除
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

