      document.body.style.overflow = ''
    }
  }, [isOpen, onClose])

  useEffect(() => {
    if (!isOpen) {
      setTitle('')
    }
  }, [isOpen])

  if (!isOpen) return null

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!title.trim()) return

    setIsSubmitting(true)
    try {
      await onSubmit(title, initialStatus)
      setTitle('')
      onClose()
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div
        className="absolute inset-0 bg-black/50"
        onClick={onClose}
      />
      <div className="relative bg-[var(--wa-surface)] rounded-sm shadow-xl w-full max-w-md mx-4 p-6 border-2 border-[var(--wa-border)]">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-lg font-semibold text-[var(--wa-text-primary)]">新規案件</h2>
          <button
            onClick={onClose}
            className="text-[var(--wa-text-muted)] hover:text-[var(--wa-text-primary)] text-2xl leading-none"
          >
            ×
          </button>
        </div>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full px-3 py-2 border border-[var(--wa-border)] rounded-sm focus:outline-none focus:ring-2 focus:ring-[var(--wa-primary-light)] mb-4 bg-[var(--wa-surface)]"
            placeholder="案件名を入力..."
            autoFocus
          />
          <div className="flex justify-end gap-2">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-[var(--wa-text-secondary)] hover:text-[var(--wa-text-primary)]"
            >
              取消
            </button>
            <button
              type="submit"
              disabled={isSubmitting || !title.trim()}
              className="px-4 py-2 bg-[var(--wa-primary)] text-white rounded-sm hover:bg-[var(--wa-primary-dark)] disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isSubmitting ? '追加中...' : '追加'}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

