@import "tailwindcss";

:root {
  /* === 和レトロカラーパレット === */

  /* 基本色 */
  --wa-background: #f5f1eb;      /* 生成り - 背景 */
  --wa-foreground: #2c2c2c;      /* 墨色 - 文字 */

  /* プライマリ（群青系） */
  --wa-primary: #223a70;         /* 群青 */
  --wa-primary-light: #3a5a9c;   /* 薄群青 */
  --wa-primary-dark: #192c54;    /* 濃群青 */

  /* セカンダリ（臙脂系） */
  --wa-secondary: #9b3a3a;       /* 臙脂 */
  --wa-secondary-light: #b85555; /* 薄臙脂 */

  /* 状態色 */
  --wa-todo: #8b8b7a;            /* 利休鼠 - 未着手 */
  --wa-doing: #2f5d50;           /* 松葉色 - 進行中 */
  --wa-done: #5c6f3d;            /* 苔色 - 完了 */
  --wa-archived: #7a7a7a;        /* 灰色 - 保管 */

  /* 中間色 */
  --wa-surface: #fffef8;         /* 象牙色 - カード背景 */
  --wa-surface-alt: #f0ebe3;     /* 薄香色 - 代替背景 */
  --wa-border: #c4b8a8;          /* 亜麻色 - ボーダー */
  --wa-border-dark: #8b7e6e;     /* 鳶色 - 濃いボーダー */

  /* テキスト色 */
  --wa-text-primary: #2c2c2c;    /* 墨色 - 主要 */
  --wa-text-secondary: #5a5a5a;  /* 鼠色 - 副次 */
  --wa-text-muted: #8a8a8a;      /* 薄墨 - ミュート */

  /* 状態背景色 */
  --wa-todo-bg: #f0efea;         /* 未着手背景 */
  --wa-doing-bg: #e8f0eb;        /* 進行中背景 */
  --wa-done-bg: #eef2e8;         /* 完了背景 */

  /* 既存変数との互換性 */
  --background: var(--wa-background);
  --foreground: var(--wa-foreground);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
}

body {
  background: var(--wa-background);
  color: var(--wa-text-primary);
}

.kanban-column {
  min-height: 400px;
}

.task-card {
  cursor: grab;
  border-radius: 4px;
}

.task-card:active {
  cursor: grabbing;
}

.task-card-dragging {
  opacity: 0.5;
  transform: rotate(2deg);
}

.drop-indicator {
  height: 2px;
  background-color: var(--wa-primary);
  margin: 4px 0;
}

/* 和レトロなフォーカススタイル */
input:focus,
textarea:focus,
button:focus-visible {
  outline: 2px solid var(--wa-primary-light);
  outline-offset: 2px;
}

/* スクロールバーのスタイル */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--wa-surface-alt);
}

::-webkit-scrollbar-thumb {
  background: var(--wa-border-dark);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--wa-text-secondary);
}

