'use client'

import { useState, useCallback } from 'react'
import {
  DndContext,
  DragOverlay,
  closestCorners,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  type DragStartEvent,
  type DragEndEvent,
} from '@dnd-kit/core'
import { sortableKeyboardCoordinates } from '@dnd-kit/sortable'
import type { Task, WorkLog, TaskStatus } from '@/types'
import { KanbanColumn } from './KanbanColumn'
import { TaskCard } from './TaskCard'
import { TaskModal } from './TaskModal'
import { AddTaskModal } from './AddTaskModal'

interface KanbanBoardProps {
  initialTasks: Task[]
  initialWorkLogs: WorkLog[]
}

const columns: { status: TaskStatus; title: string }[] = [
  { status: 'todo', title: '未着手' },
  { status: 'doing', title: '進行中' },
  { status: 'done', title: '完了' },
]

export function KanbanBoard({ initialTasks, initialWorkLogs }: KanbanBoardProps) {
  const [tasks, setTasks] = useState<Task[]>(initialTasks)
  const [workLogs, setWorkLogs] = useState<WorkLog[]>(initialWorkLogs)
  const [activeTask, setActiveTask] = useState<Task | null>(null)
  const [selectedTask, setSelectedTask] = useState<Task | null>(null)
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false)
  const [isAddModalOpen, setIsAddModalOpen] = useState(false)
  const [addTaskStatus, setAddTaskStatus] = useState<TaskStatus>('todo')

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  )

  const getTasksByStatus = (status: TaskStatus) =>
    tasks.filter((task) => task.status === status)

  const handleDragStart = (event: DragStartEvent) => {
    const task = tasks.find((t) => t.id === event.active.id)
    if (task) {
      setActiveTask(task)
    }
  }

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event
    setActiveTask(null)

    if (!over) return

    const activeId = active.id as string
    const overId = over.id as string

    const activeTaskData = tasks.find((t) => t.id === activeId)
    if (!activeTaskData) return

    let newStatus: TaskStatus
    let newPosition: number

    const overTask = tasks.find((t) => t.id === overId)
    if (overTask) {
      newStatus = overTask.status
      const tasksInColumn = tasks.filter((t) => t.status === newStatus)
      const overIndex = tasksInColumn.findIndex((t) => t.id === overId)
      newPosition = overIndex
    } else {
      newStatus = overId as TaskStatus
      const tasksInColumn = tasks.filter((t) => t.status === newStatus)
      newPosition = tasksInColumn.length
    }

    if (activeTaskData.status === newStatus) {
      const tasksInColumn = tasks
        .filter((t) => t.status === newStatus)
        .sort((a, b) => a.position - b.position)
      const oldIndex = tasksInColumn.findIndex((t) => t.id === activeId)
      if (oldIndex === newPosition) return
    }

    const updatedTasks = tasks.map((t) => {
      if (t.id === activeId) {
        return { ...t, status: newStatus, position: newPosition }
      }
      return t
    })
    setTasks(updatedTasks)

    try {
      const response = await fetch('/api/tasks/reorder', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          taskId: activeId,
          newStatus,
          newPosition,
        }),
      })

      if (response.ok) {
        const data = await response.json()
        if (data.success) {
          setTasks(data.data)
        }
      }
    } catch {
      setTasks(initialTasks)
    }
  }

  const handleTaskClick = useCallback((task: Task) => {
    setSelectedTask(task)
    setIsTaskModalOpen(true)
  }, [])

  const handleAddTaskClick = useCallback((status: TaskStatus) => {
    setAddTaskStatus(status)
    setIsAddModalOpen(true)
  }, [])

  const handleAddTask = async (title: string, status: TaskStatus) => {
    const response = await fetch('/api/tasks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title, status }),
    })

    if (response.ok) {
      const data = await response.json()
      if (data.success) {
        setTasks((prev) => [...prev, data.data])
      }
    }
  }

  const handleUpdateTask = async (updates: Partial<Task>) => {
    if (!selectedTask) return

    const response = await fetch(`/api/tasks/${selectedTask.id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(updates),
    })

    if (response.ok) {
      const data = await response.json()
      if (data.success) {
        setTasks((prev) =>
          prev.map((t) => (t.id === selectedTask.id ? data.data : t))
        )
        setSelectedTask(data.data)
      }
    }
  }

  const handleDeleteTask = async () => {
    if (!selectedTask) return

    const response = await fetch(`/api/tasks/${selectedTask.id}`, {
      method: 'DELETE',
    })

    if (response.ok) {
      setTasks((prev) => prev.filter((t) => t.id !== selectedTask.id))
      setWorkLogs((prev) => prev.filter((w) => w.taskId !== selectedTask.id))
      setIsTaskModalOpen(false)
      setSelectedTask(null)
    }
  }

  const handleArchiveTask = async () => {
    if (!selectedTask) return
    await handleUpdateTask({ status: 'archived' })
    setIsTaskModalOpen(false)
    setSelectedTask(null)
  }

  const handleAddWorkLog = async (content: string, date: string) => {
    if (!selectedTask) return

    const response = await fetch('/api/worklogs', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        taskId: selectedTask.id,
        content,
        date,
      }),
    })

    if (response.ok) {
      const data = await response.json()
      if (data.success) {
        setWorkLogs((prev) => [...prev, data.data])
      }
    }
  }

  const handleDeleteWorkLog = async (id: string) => {
    const response = await fetch(`/api/worklogs/${id}`, {
      method: 'DELETE',
    })

    if (response.ok) {
      setWorkLogs((prev) => prev.filter((w) => w.id !== id))
    }
  }

  const selectedTaskWorkLogs = selectedTask
    ? workLogs.filter((w) => w.taskId === selectedTask.id)
    : []

  return (
    <>
      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="flex gap-4 overflow-x-auto pb-4">
          {columns.map(({ status, title }) => (
            <KanbanColumn
              key={status}
              status={status}
              title={title}
              tasks={getTasksByStatus(status)}
              workLogs={workLogs}
              onTaskClick={handleTaskClick}
              onAddTask={() => handleAddTaskClick(status)}
            />
          ))}
        </div>
        <DragOverlay>
          {activeTask && (
            <div className="opacity-80">
              <TaskCard
                task={activeTask}
                onClick={() => {}}
              />
            </div>
          )}
        </DragOverlay>
      </DndContext>

      {selectedTask && (
        <TaskModal
          task={selectedTask}
          workLogs={selectedTaskWorkLogs}
          isOpen={isTaskModalOpen}
          onClose={() => {
            setIsTaskModalOpen(false)
            setSelectedTask(null)
          }}
          onUpdate={handleUpdateTask}
          onDelete={handleDeleteTask}
          onArchive={handleArchiveTask}
          onAddWorkLog={handleAddWorkLog}
          onDeleteWorkLog={handleDeleteWorkLog}
        />
      )}

      <AddTaskModal
        isOpen={isAddModalOpen}
        initialStatus={addTaskStatus}
        onClose={() => setIsAddModalOpen(false)}
        onSubmit={handleAddTask}
      />
    </>
  )
}

'use client'

import { useDroppable } from '@dnd-kit/core'
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable'
import type { Task, WorkLog, TaskStatus } from '@/types'
import { TaskCard } from './TaskCard'
import { cn } from '@/lib/utils'

interface KanbanColumnProps {
  status: TaskStatus
  title: string
  tasks: Task[]
  workLogs: WorkLog[]
  onTaskClick: (task: Task) => void
  onAddTask: () => void
}

const columnColors: Record<TaskStatus, string> = {
  todo: 'bg-[var(--wa-todo-bg)] border-[var(--wa-todo)]',
  doing: 'bg-[var(--wa-doing-bg)] border-[var(--wa-doing)]',
  done: 'bg-[var(--wa-done-bg)] border-[var(--wa-done)]',
  archived: 'bg-[var(--wa-surface-alt)] border-[var(--wa-border-dark)]',
}

const headerColors: Record<TaskStatus, string> = {
  todo: 'text-[var(--wa-todo)]',
  doing: 'text-[var(--wa-doing)]',
  done: 'text-[var(--wa-done)]',
  archived: 'text-[var(--wa-archived)]',
}

export function KanbanColumn({
  status,
  title,
  tasks,
  workLogs,
  onTaskClick,
  onAddTask,
}: KanbanColumnProps) {
  const { setNodeRef, isOver } = useDroppable({ id: status })

  const sortedTasks = [...tasks].sort((a, b) => a.position - b.position)
  const taskIds = sortedTasks.map((t) => t.id)

  const getLatestWorkLog = (taskId: string): WorkLog | undefined => {
    const taskLogs = workLogs
      .filter((w) => w.taskId === taskId)
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
    return taskLogs[0]
  }

  return (
    <div
      ref={setNodeRef}
      className={cn(
        'kanban-column flex-1 min-w-[280px] max-w-[350px] rounded-sm border-2 p-4 transition-colors',
        columnColors[status],
        isOver && 'border-[var(--wa-primary)] bg-[#e8ebf5]'
      )}
    >
      <div className="flex justify-between items-center mb-4">
        <h2 className={cn('font-semibold text-lg', headerColors[status])}>
          {title}
          <span className="ml-2 text-sm font-normal text-[var(--wa-text-muted)]">
            ({tasks.length})
          </span>
        </h2>
        {status !== 'archived' && (
          <button
            onClick={onAddTask}
            className="text-[var(--wa-text-muted)] hover:text-[var(--wa-text-primary)] text-xl leading-none transition-colors"
            title="案件を追加"
          >
            +
          </button>
        )}
      </div>
      <SortableContext items={taskIds} strategy={verticalListSortingStrategy}>
        <div className="space-y-0">
          {sortedTasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              latestWorkLog={getLatestWorkLog(task.id)}
              onClick={() => onTaskClick(task)}
            />
          ))}
        </div>
      </SortableContext>
      {tasks.length === 0 && (
        <p className="text-[var(--wa-text-muted)] text-sm text-center py-8">案件なし</p>
      )}
    </div>
  )
}

'use client'

import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import type { Task, WorkLog } from '@/types'
import { cn, getDueStatus, formatDate, type DueStatus } from '@/lib/utils'

interface TaskCardProps {
  task: Task
  latestWorkLog?: WorkLog
  onClick: () => void
}

function TrafficLight({ status, isDone }: { status: DueStatus; isDone: boolean }) {
  if (status === 'none') return null

  const getColor = () => {
    if (isDone) return 'bg-gray-400'
    switch (status) {
      case 'safe':
        return 'bg-green-500'
      case 'warning':
        return 'bg-yellow-500'
      case 'danger':
        return 'bg-red-500'
      default:
        return 'bg-gray-400'
    }
  }

  return (
    <span
      className={cn(
        'inline-block w-3 h-3 rounded-full shrink-0',
        getColor()
      )}
      title={
        isDone
          ? '完了'
          : status === 'safe'
          ? '余裕あり'
          : status === 'warning'
          ? '期限間近'
          : '期限切れ'
      }
    />
  )
}

export function TaskCard({ task, latestWorkLog, onClick }: TaskCardProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: task.id })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  }

  const dueStatus = getDueStatus(task.dueDate)
  const isDone = task.status === 'done'

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      onClick={onClick}
      className={cn(
        'task-card bg-[var(--wa-surface)] rounded-sm shadow-sm border border-[var(--wa-border)] p-4 mb-3 hover:shadow-md transition-shadow',
        isDragging && 'task-card-dragging shadow-lg',
        !isDone && dueStatus === 'danger' && 'border-[var(--wa-secondary)] border-2'
      )}
    >
      <div className="flex items-start gap-2">
        <TrafficLight status={dueStatus} isDone={isDone} />
        <div className="flex-1 min-w-0">
          <h3 className="font-medium text-[var(--wa-text-primary)] mb-1 line-clamp-2">
            {task.title}
          </h3>
          {task.dueDate && (
            <p
              className={cn(
                'text-xs',
                !isDone && dueStatus === 'danger'
                  ? 'text-[var(--wa-secondary)] font-medium'
                  : 'text-[var(--wa-text-secondary)]'
              )}
            >
              期限: {formatDate(task.dueDate)}
            </p>
          )}
        </div>
      </div>
      {latestWorkLog && (
        <p className="text-xs text-[var(--wa-text-muted)] line-clamp-1 mt-2 pl-5">
          {latestWorkLog.content}
        </p>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import type { Task, WorkLog, TaskStatus } from '@/types'
import { formatDate, formatDateTime, cn } from '@/lib/utils'

interface TaskModalProps {
  task: Task
  workLogs: WorkLog[]
  isOpen: boolean
  onClose: () => void
  onUpdate: (updates: Partial<Task>) => Promise<void>
  onDelete: () => Promise<void>
  onArchive: () => Promise<void>
  onAddWorkLog: (content: string, date: string) => Promise<void>
  onDeleteWorkLog: (id: string) => Promise<void>
}

function getTodayDateString(): string {
  const now = new Date()
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`
}

const statusLabels: Record<TaskStatus, string> = {
  todo: '未着手',
  doing: '進行中',
  done: '完了',
  archived: '保管済',
}

const statusColors: Record<TaskStatus, string> = {
  todo: 'bg-[#e8e8e0] text-[var(--wa-todo)]',
  doing: 'bg-[#d8e8e0] text-[var(--wa-doing)]',
  done: 'bg-[#e0e8d8] text-[var(--wa-done)]',
  archived: 'bg-[#e0e0e0] text-[var(--wa-archived)]',
}

export function TaskModal({
  task,
  workLogs,
  isOpen,
  onClose,
  onUpdate,
  onDelete,
  onArchive,
  onAddWorkLog,
  onDeleteWorkLog,
}: TaskModalProps) {
  const [title, setTitle] = useState(task.title)
  const [description, setDescription] = useState(task.description)
  const [dueDate, setDueDate] = useState(task.dueDate ?? '')
  const [newWorkLogContent, setNewWorkLogContent] = useState('')
  const [newWorkLogDate, setNewWorkLogDate] = useState(getTodayDateString())
  const [isSubmitting, setIsSubmitting] = useState(false)

  useEffect(() => {
    setTitle(task.title)
    setDescription(task.description)
    setDueDate(task.dueDate ?? '')
  }, [task])

  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    if (isOpen) {
      document.addEventListener('keydown', handleEscape)
      document.body.style.overflow = 'hidden'
    }
    return () => {
      document.removeEventListener('keydown', handleEscape)
      document.body.style.overflow = ''
    }
  }, [isOpen, onClose])

  if (!isOpen) return null

  const handleSave = async () => {
    setIsSubmitting(true)
    try {
      await onUpdate({
        title,
        description,
        dueDate: dueDate || null,
      })
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleStatusChange = async (newStatus: TaskStatus) => {
    setIsSubmitting(true)
    try {
      await onUpdate({ status: newStatus })
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleAddWorkLog = async () => {
    if (!newWorkLogContent.trim()) return
    setIsSubmitting(true)
    try {
      await onAddWorkLog(newWorkLogContent, newWorkLogDate)
      setNewWorkLogContent('')
      setNewWorkLogDate(getTodayDateString())
    } finally {
      setIsSubmitting(false)
    }
  }

  const sortedWorkLogs = [...workLogs].sort(
    (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  )

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div
        className="absolute inset-0 bg-black/50"
        onClick={onClose}
      />
      <div className="relative bg-[var(--wa-surface)] rounded-sm shadow-xl w-full max-w-2xl max-h-[90vh] overflow-hidden mx-4 border-2 border-[var(--wa-border)]">
        <div className="p-6 overflow-y-auto max-h-[90vh]">
          <div className="flex justify-between items-start mb-4">
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              onBlur={handleSave}
              className="text-xl font-bold text-[var(--wa-text-primary)] w-full border-0 border-b-2 border-transparent focus:border-[var(--wa-primary)] focus:outline-none bg-transparent"
            />
            <button
              onClick={onClose}
              className="ml-4 text-[var(--wa-text-muted)] hover:text-[var(--wa-text-primary)] text-2xl leading-none"
            >
              ×
            </button>
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-[var(--wa-text-secondary)] mb-2">
              状態
            </label>
            <div className="flex flex-wrap gap-2">
              {(['todo', 'doing', 'done'] as TaskStatus[]).map((status) => (
                <button
                  key={status}
                  onClick={() => handleStatusChange(status)}
                  disabled={isSubmitting}
                  className={cn(
                    'px-3 py-1 rounded-sm text-sm font-medium transition-colors',
                    task.status === status
                      ? statusColors[status]
                      : 'bg-[var(--wa-surface-alt)] text-[var(--wa-text-secondary)] hover:bg-[var(--wa-border)]'
                  )}
                >
                  {statusLabels[status]}
                </button>
              ))}
            </div>
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-[var(--wa-text-secondary)] mb-2">
              期限
            </label>
            <input
              type="date"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
              onBlur={handleSave}
              className="px-3 py-2 border border-[var(--wa-border)] rounded-sm focus:outline-none focus:ring-2 focus:ring-[var(--wa-primary-light)] bg-[var(--wa-surface)]"
            />
            {dueDate && (
              <button
                onClick={() => {
                  setDueDate('')
                  onUpdate({ dueDate: null })
                }}
                className="ml-2 text-sm text-[var(--wa-text-muted)] hover:text-[var(--wa-text-primary)]"
              >
                解除
              </button>
            )}
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-[var(--wa-text-secondary)] mb-2">
              詳細
            </label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              onBlur={handleSave}
              rows={4}
              className="w-full px-3 py-2 border border-[var(--wa-border)] rounded-sm focus:outline-none focus:ring-2 focus:ring-[var(--wa-primary-light)] resize-none bg-[var(--wa-surface)]"
              placeholder="詳細を入力..."
            />
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-[var(--wa-text-secondary)] mb-2">
              作業記録
            </label>
            <div className="space-y-2 mb-4">
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newWorkLogContent}
                  onChange={(e) => setNewWorkLogContent(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.nativeEvent.isComposing) {
                      handleAddWorkLog()
                    }
                  }}
                  className="flex-1 px-3 py-2 border border-[var(--wa-border)] rounded-sm focus:outline-none focus:ring-2 focus:ring-[var(--wa-primary-light)] bg-[var(--wa-surface)]"
                  placeholder="作業記録を追加..."
                />
                <button
                  onClick={handleAddWorkLog}
                  disabled={isSubmitting || !newWorkLogContent.trim()}
                  className="px-4 py-2 bg-[var(--wa-primary)] text-white rounded-sm hover:bg-[var(--wa-primary-dark)] disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  追加
                </button>
              </div>
              <div className="flex items-center gap-2">
                <label className="text-xs text-[var(--wa-text-muted)]">日付:</label>
                <input
                  type="date"
                  value={newWorkLogDate}
                  onChange={(e) => setNewWorkLogDate(e.target.value)}
                  className="px-2 py-1 text-sm border border-[var(--wa-border)] rounded-sm focus:outline-none focus:ring-2 focus:ring-[var(--wa-primary-light)] bg-[var(--wa-surface)]"
                />
                {newWorkLogDate !== getTodayDateString() && (
                  <button
                    type="button"
                    onClick={() => setNewWorkLogDate(getTodayDateString())}
                    className="text-xs text-[var(--wa-text-muted)] hover:text-[var(--wa-primary)] underline"
                  >
                    今日に戻す
                  </button>
                )}
              </div>
            </div>
            <div className="space-y-3 max-h-48 overflow-y-auto">
              {sortedWorkLogs.map((log) => (
                <div
                  key={log.id}
                  className="flex justify-between items-start p-3 bg-[var(--wa-surface-alt)] rounded-sm"
                >
                  <div className="flex-1">
                    <p className="text-sm text-[var(--wa-text-primary)]">{log.content}</p>
                    <p className="text-xs text-[var(--wa-text-muted)] mt-1">
                      {formatDate(log.date)} - {formatDateTime(log.createdAt)}
                    </p>
                  </div>
                  <button
                    onClick={() => onDeleteWorkLog(log.id)}
                    className="ml-2 text-[var(--wa-text-muted)] hover:text-[var(--wa-secondary)]"
                  >
                    ×
                  </button>
                </div>
              ))}
              {sortedWorkLogs.length === 0 && (
                <p className="text-sm text-[var(--wa-text-muted)] text-center py-4">
                  作業記録はありません
                </p>
              )}
            </div>
          </div>

          <div className="flex justify-between pt-4 border-t border-[var(--wa-border)]">
            <div className="flex gap-2">
              {task.status === 'done' && (
                <button
                  onClick={onArchive}
                  disabled={isSubmitting}
                  className="px-4 py-2 bg-[var(--wa-border-dark)] text-white rounded-sm hover:bg-[var(--wa-text-secondary)] disabled:opacity-50"
                >
                  保管
                </button>
              )}
            </div>
            <button
              onClick={onDelete}
              disabled={isSubmitting}
              className="px-4 py-2 bg-[var(--wa-secondary)] text-white rounded-sm hover:bg-[var(--wa-secondary-light)] disabled:opacity-50"
            >
              削除
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import type { TaskStatus } from '@/types'

interface AddTaskModalProps {
  isOpen: boolean
  initialStatus: TaskStatus
  onClose: () => void
  onSubmit: (title: string, status: TaskStatus) => Promise<void>
}

export function AddTaskModal({
  isOpen,
  initialStatus,
  onClose,
  onSubmit,
}: AddTaskModalProps) {
  const [title, setTitle] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)

  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    if (isOpen) {
      document.addEventListener('keydown', handleEscape)
      document.body.style.overflow = 'hidden'
    }
    return () => {
      document.removeEventListener('keydown', handleEscape)
      document.body.style.overflow = ''
    }
  }, [isOpen, onClose])

  useEffect(() => {
    if (!isOpen) {
      setTitle('')
    }
  }, [isOpen])

  if (!isOpen) return null

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!title.trim()) return

    setIsSubmitting(true)
    try {
      await onSubmit(title, initialStatus)
      setTitle('')
      onClose()
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div
        className="absolute inset-0 bg-black/50"
        onClick={onClose}
      />
      <div className="relative bg-[var(--wa-surface)] rounded-sm shadow-xl w-full max-w-md mx-4 p-6 border-2 border-[var(--wa-border)]">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-lg font-semibold text-[var(--wa-text-primary)]">新規案件</h2>
          <button
            onClick={onClose}
            className="text-[var(--wa-text-muted)] hover:text-[var(--wa-text-primary)] text-2xl leading-none"
          >
            ×
          </button>
        </div>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full px-3 py-2 border border-[var(--wa-border)] rounded-sm focus:outline-none focus:ring-2 focus:ring-[var(--wa-primary-light)] mb-4 bg-[var(--wa-surface)]"
            placeholder="案件名を入力..."
            autoFocus
          />
          <div className="flex justify-end gap-2">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-[var(--wa-text-secondary)] hover:text-[var(--wa-text-primary)]"
            >
              取消
            </button>
            <button
              type="submit"
              disabled={isSubmitting || !title.trim()}
              className="px-4 py-2 bg-[var(--wa-primary)] text-white rounded-sm hover:bg-[var(--wa-primary-dark)] disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isSubmitting ? '追加中...' : '追加'}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

input.content:
'use client'

import { useState, useCallback } from 'react'
import {
  DndContext,
  DragOverlay,
  closestCorners,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  type DragStartEvent,
  type DragEndEvent,
} from '@dnd-kit/core'
import { sortableKeyboardCoordinates } from '@dnd-kit/sortable'
import type { Task, WorkLog, TaskStatus } from '@/types'
import { KanbanColumn } from './KanbanColumn'
import { TaskCard } from './TaskCard'
import { TaskModal } from './TaskModal'
import { AddTaskModal } from './AddTaskModal'

interface KanbanBoardProps {
  initialTasks: Task[]
  initialWorkLogs: WorkLog[]
}

