'use client'

import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import type { Task, WorkLog } from '@/types'
import { cn, getDueStatus, formatDate, type DueStatus } from '@/lib/utils'

interface TaskCardProps {
  task: Task
  latestWorkLog?: WorkLog
  onClick: () => void
}

function TrafficLight({ status, isDone }: { status: DueStatus; isDone: boolean }) {
  if (status === 'none') return null

  const getColor = () => {
    if (isDone) return 'bg-gray-400'
    switch (status) {
      case 'safe':
        return 'bg-green-500'
      case 'warning':
        return 'bg-yellow-500'
      case 'danger':
        return 'bg-red-500'
      default:
        return 'bg-gray-400'
    }
  }

  return (
    <span
      className={cn(
        'inline-block w-3 h-3 rounded-full shrink-0',
        getColor()
      )}
      title={
        isDone
          ? 'Completed'
          : status === 'safe'
          ? 'On track'
          : status === 'warning'
          ? 'Due soon'
          : 'Overdue'
      }
    />
  )
}

export function TaskCard({ task, latestWorkLog, onClick }: TaskCardProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: task.id })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  }

  const dueStatus = getDueStatus(task.dueDate)
  const isDone = task.status === 'done'

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      onClick={onClick}
      className={cn(
        'task-card bg-[var(--tw-surface)] rounded-lg shadow-sm border border-[var(--tw-border)] p-4 mb-3 hover:shadow-md transition-shadow',
        isDragging && 'task-card-dragging shadow-lg',
        !isDone && dueStatus === 'danger' && 'border-[var(--tw-primary)] border-2'
      )}
    >
      <div className="flex items-start gap-2">
        <TrafficLight status={dueStatus} isDone={isDone} />
        <div className="flex-1 min-w-0">
          <h3 className="font-medium text-[var(--tw-text-primary)] mb-1 line-clamp-2">
            {task.title}
          </h3>
          {task.dueDate && (
            <p
              className={cn(
                'text-xs',
                !isDone && dueStatus === 'danger'
                  ? 'text-[var(--tw-primary)] font-medium'
                  : 'text-[var(--tw-text-secondary)]'
              )}
            >
              Due: {formatDate(task.dueDate)}
            </p>
          )}
        </div>
      </div>
      {latestWorkLog && (
        <p className="text-xs text-[var(--tw-text-muted)] line-clamp-1 mt-2 pl-5">
          {latestWorkLog.content}
        </p>
      )}
    </div>
  )
}

