'use client'

import { useState, useEffect } from 'react'
import type { Task, WorkLog, TaskStatus } from '@/types'
import { formatDate, formatDateTime, cn } from '@/lib/utils'

interface TaskModalProps {
  task: Task
  workLogs: WorkLog[]
  isOpen: boolean
  onClose: () => void
  onUpdate: (updates: Partial<Task>) => Promise<void>
  onDelete: () => Promise<void>
  onArchive: () => Promise<void>
  onAddWorkLog: (content: string, date: string) => Promise<void>
  onDeleteWorkLog: (id: string) => Promise<void>
}

function getTodayDateString(): string {
  const now = new Date()
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`
}

const statusLabels: Record<TaskStatus, string> = {
  todo: 'To Do',
  doing: 'In Progress',
  done: 'Done',
  archived: 'Archived',
}

const statusColors: Record<TaskStatus, string> = {
  todo: 'bg-[var(--tw-todo-bg)] text-[var(--tw-todo)]',
  doing: 'bg-[var(--tw-doing-bg)] text-[var(--tw-doing)]',
  done: 'bg-[var(--tw-done-bg)] text-[var(--tw-done)]',
  archived: 'bg-[var(--tw-surface-alt)] text-[var(--tw-archived)]',
}

export function TaskModal({
  task,
  workLogs,
  isOpen,
  onClose,
  onUpdate,
  onDelete,
  onArchive,
  onAddWorkLog,
  onDeleteWorkLog,
}: TaskModalProps) {
  const [title, setTitle] = useState(task.title)
  const [description, setDescription] = useState(task.description)
  const [dueDate, setDueDate] = useState(task.dueDate ?? '')
  const [newWorkLogContent, setNewWorkLogContent] = useState('')
  const [newWorkLogDate, setNewWorkLogDate] = useState(getTodayDateString())
  const [isSubmitting, setIsSubmitting] = useState(false)

  useEffect(() => {
    setTitle(task.title)
    setDescription(task.description)
    setDueDate(task.dueDate ?? '')
  }, [task])

  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    if (isOpen) {
      document.addEventListener('keydown', handleEscape)
      document.body.style.overflow = 'hidden'
    }
    return () => {
      document.removeEventListener('keydown', handleEscape)
      document.body.style.overflow = ''
    }
  }, [isOpen, onClose])

  if (!isOpen) return null

  const handleSave = async () => {
    setIsSubmitting(true)
    try {
      await onUpdate({
        title,
        description,
        dueDate: dueDate || null,
      })
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleStatusChange = async (newStatus: TaskStatus) => {
    setIsSubmitting(true)
    try {
      await onUpdate({ status: newStatus })
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleAddWorkLog = async () => {
    if (!newWorkLogContent.trim()) return
    setIsSubmitting(true)
    try {
      await onAddWorkLog(newWorkLogContent, newWorkLogDate)
      setNewWorkLogContent('')
      setNewWorkLogDate(getTodayDateString())
    } finally {
      setIsSubmitting(false)
    }
  }

  const sortedWorkLogs = [...workLogs].sort(
    (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  )

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div
        className="absolute inset-0 bg-black/50"
        onClick={onClose}
      />
      <div className="relative bg-[var(--tw-surface)] rounded-xl shadow-xl w-full max-w-2xl max-h-[90vh] overflow-hidden mx-4 border border-[var(--tw-border)]">
        <div className="p-6 overflow-y-auto max-h-[90vh]">
          <div className="flex justify-between items-start mb-4">
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              onBlur={handleSave}
              className="text-xl font-bold text-[var(--tw-text-primary)] w-full border-0 border-b-2 border-transparent focus:border-[var(--tw-primary)] focus:outline-none bg-transparent"
            />
            <button
              onClick={onClose}
              className="ml-4 text-[var(--tw-text-muted)] hover:text-[var(--tw-text-primary)] text-2xl leading-none"
            >
              ×
            </button>
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-[var(--tw-text-secondary)] mb-2">
              Status
            </label>
            <div className="flex flex-wrap gap-2">
              {(['todo', 'doing', 'done'] as TaskStatus[]).map((status) => (
                <button
                  key={status}
                  onClick={() => handleStatusChange(status)}
                  disabled={isSubmitting}
                  className={cn(
                    'px-3 py-1 rounded-lg text-sm font-medium transition-colors',
                    task.status === status
                      ? statusColors[status]
                      : 'bg-[var(--tw-surface-alt)] text-[var(--tw-text-secondary)] hover:bg-[var(--tw-border)]'
                  )}
                >
                  {statusLabels[status]}
                </button>
              ))}
            </div>
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-[var(--tw-text-secondary)] mb-2">
              Due Date
            </label>
            <input
              type="date"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
              onBlur={handleSave}
              className="px-3 py-2 border border-[var(--tw-border)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--tw-primary)] bg-[var(--tw-surface)]"
            />
            {dueDate && (
              <button
                onClick={() => {
                  setDueDate('')
                  onUpdate({ dueDate: null })
                }}
                className="ml-2 text-sm text-[var(--tw-text-muted)] hover:text-[var(--tw-text-primary)]"
              >
                Clear
              </button>
            )}
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-[var(--tw-text-secondary)] mb-2">
              Description
            </label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              onBlur={handleSave}
              rows={4}
              className="w-full px-3 py-2 border border-[var(--tw-border)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--tw-primary)] resize-none bg-[var(--tw-surface)]"
              placeholder="Add a description..."
            />
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-[var(--tw-text-secondary)] mb-2">
              Work Log
            </label>
            <div className="space-y-2 mb-4">
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newWorkLogContent}
                  onChange={(e) => setNewWorkLogContent(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.nativeEvent.isComposing) {
                      handleAddWorkLog()
                    }
                  }}
                  className="flex-1 px-3 py-2 border border-[var(--tw-border)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--tw-primary)] bg-[var(--tw-surface)]"
                  placeholder="Add work log entry..."
                />
                <button
                  onClick={handleAddWorkLog}
                  disabled={isSubmitting || !newWorkLogContent.trim()}
                  className="px-4 py-2 bg-[var(--tw-primary)] text-white rounded-lg hover:bg-[var(--tw-primary-dark)] disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  Add
                </button>
              </div>
              <div className="flex items-center gap-2">
                <label className="text-xs text-[var(--tw-text-muted)]">Date:</label>
                <input
                  type="date"
                  value={newWorkLogDate}
                  onChange={(e) => setNewWorkLogDate(e.target.value)}
                  className="px-2 py-1 text-sm border border-[var(--tw-border)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--tw-primary)] bg-[var(--tw-surface)]"
                />
                {newWorkLogDate !== getTodayDateString() && (
                  <button
                    type="button"
                    onClick={() => setNewWorkLogDate(getTodayDateString())}
                    className="text-xs text-[var(--tw-text-muted)] hover:text-[var(--tw-primary)] underline"
                  >
                    Reset to today
                  </button>
                )}
              </div>
            </div>
            <div className="space-y-3 max-h-48 overflow-y-auto">
              {sortedWorkLogs.map((log) => (
                <div
                  key={log.id}
                  className="flex justify-between items-start p-3 bg-[var(--tw-surface-alt)] rounded-lg"
                >
                  <div className="flex-1">
                    <p className="text-sm text-[var(--tw-text-primary)]">{log.content}</p>
                    <p className="text-xs text-[var(--tw-text-muted)] mt-1">
                      {formatDate(log.date)} - {formatDateTime(log.createdAt)}
                    </p>
                  </div>
                  <button
                    onClick={() => onDeleteWorkLog(log.id)}
                    className="ml-2 text-[var(--tw-text-muted)] hover:text-[var(--tw-primary)]"
                  >
                    ×
                  </button>
                </div>
              ))}
              {sortedWorkLogs.length === 0 && (
                <p className="text-sm text-[var(--tw-text-muted)] text-center py-4">
                  No work logs yet
                </p>
              )}
            </div>
          </div>

          <div className="flex justify-between pt-4 border-t border-[var(--tw-border)]">
            <div className="flex gap-2">
              {task.status === 'done' && (
                <button
                  onClick={onArchive}
                  disabled={isSubmitting}
                  className="px-4 py-2 bg-[var(--tw-border-dark)] text-white rounded-lg hover:bg-[var(--tw-text-secondary)] disabled:opacity-50"
                >
                  Archive
                </button>
              )}
            </div>
            <button
              onClick={onDelete}
              disabled={isSubmitting}
              className="px-4 py-2 bg-[var(--tw-primary)] text-white rounded-lg hover:bg-[var(--tw-primary-dark)] disabled:opacity-50"
            >
              Delete
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

