'use client'

import { useState, useMemo } from 'react'
import type { WorkLog, Task } from '@/types'
import { formatDate, formatDateTime } from '@/lib/utils'

interface DailyViewProps {
  workLogs: WorkLog[]
  tasks: Task[]
}

export function DailyView({ workLogs, tasks }: DailyViewProps) {
  const [filterDate, setFilterDate] = useState('')

  const taskMap = useMemo(() => {
    const map = new Map<string, Task>()
    tasks.forEach((task) => map.set(task.id, task))
    return map
  }, [tasks])

  const groupedLogs = useMemo(() => {
    const filtered = filterDate
      ? workLogs.filter((log) => log.date === filterDate)
      : workLogs

    const groups = new Map<string, WorkLog[]>()

    filtered.forEach((log) => {
      const existing = groups.get(log.date) ?? []
      groups.set(log.date, [...existing, log])
    })

    return Array.from(groups.entries())
      .sort(([a], [b]) => b.localeCompare(a))
      .map(([date, logs]) => ({
        date,
        logs: logs.sort(
          (a, b) =>
            new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        ),
      }))
  }, [workLogs, filterDate])

  return (
    <div>
      <div className="mb-6 flex items-center gap-4">
        <label className="text-sm font-medium text-[var(--wa-text-secondary)]">
          日付で絞り込み:
        </label>
        <input
          type="date"
          value={filterDate}
          onChange={(e) => setFilterDate(e.target.value)}
          className="px-3 py-2 border border-[var(--wa-border)] rounded-sm focus:outline-none focus:ring-2 focus:ring-[var(--wa-primary-light)] bg-[var(--wa-surface)]"
        />
        {filterDate && (
          <button
            onClick={() => setFilterDate('')}
            className="text-sm text-[var(--wa-text-muted)] hover:text-[var(--wa-text-primary)]"
          >
            絞り込み解除
          </button>
        )}
      </div>

      {groupedLogs.length === 0 ? (
        <div className="bg-[var(--wa-surface)] rounded-sm shadow-sm p-8 text-center border border-[var(--wa-border)]">
          <p className="text-[var(--wa-text-muted)]">作業記録がありません</p>
        </div>
      ) : (
        <div className="space-y-6">
          {groupedLogs.map(({ date, logs }) => (
            <div key={date} className="bg-[var(--wa-surface)] rounded-sm shadow-sm overflow-hidden border border-[var(--wa-border)]">
              <div className="bg-[var(--wa-surface-alt)] px-6 py-3 border-b border-[var(--wa-border)]">
                <h2 className="font-semibold text-[var(--wa-text-primary)]">
                  {formatDate(date)}
                </h2>
                <p className="text-sm text-[var(--wa-text-muted)]">{logs.length} 件</p>
              </div>
              <div className="divide-y divide-[var(--wa-surface-alt)]">
                {logs.map((log) => {
                  const task = taskMap.get(log.taskId)
                  return (
                    <div key={log.id} className="px-6 py-4">
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <p className="text-[var(--wa-text-primary)]">{log.content}</p>
                          <div className="mt-1 flex items-center gap-2 text-sm text-[var(--wa-text-muted)]">
                            {task && (
                              <>
                                <span className="inline-flex items-center px-2 py-0.5 rounded-sm text-xs font-medium bg-[var(--wa-surface-alt)] text-[var(--wa-text-secondary)]">
                                  {task.title}
                                </span>
                                {task.status === 'archived' && (
                                  <span className="text-xs text-[var(--wa-text-muted)]">
                                    （保管済）
                                  </span>
                                )}
                              </>
                            )}
                          </div>
                        </div>
                        <span className="text-xs text-[var(--wa-text-muted)] ml-4 whitespace-nowrap">
                          {formatDateTime(log.createdAt)}
                        </span>
                      </div>
                    </div>
                  )
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useMemo } from 'react'
import {
  startOfWeek,
  endOfWeek,
  addWeeks,
  subWeeks,
  format,
  eachDayOfInterval,
  isSameDay,
  parseISO,
} from 'date-fns'
import { ja } from 'date-fns/locale'
import type { WorkLog, Task } from '@/types'
import { cn } from '@/lib/utils'

interface WeeklyViewProps {
  workLogs: WorkLog[]
  tasks: Task[]
}

export function WeeklyView({ workLogs, tasks }: WeeklyViewProps) {
  const [currentWeekStart, setCurrentWeekStart] = useState(() =>
    startOfWeek(new Date(), { weekStartsOn: 1 })
  )

  const weekEnd = endOfWeek(currentWeekStart, { weekStartsOn: 1 })

  const daysOfWeek = useMemo(
    () => eachDayOfInterval({ start: currentWeekStart, end: weekEnd }),
    [currentWeekStart, weekEnd]
  )

  const taskMap = useMemo(() => {
    const map = new Map<string, Task>()
    tasks.forEach((task) => map.set(task.id, task))
    return map
  }, [tasks])

  const weeklyLogs = useMemo(() => {
    return workLogs.filter((log) => {
      const logDate = parseISO(log.date)
      return logDate >= currentWeekStart && logDate <= weekEnd
    })
  }, [workLogs, currentWeekStart, weekEnd])

  const logsByDay = useMemo(() => {
    const map = new Map<string, WorkLog[]>()
    daysOfWeek.forEach((day) => {
      const dayStr = format(day, 'yyyy-MM-dd')
      map.set(dayStr, [])
    })
    weeklyLogs.forEach((log) => {
      const existing = map.get(log.date) ?? []
      map.set(log.date, [...existing, log])
    })
    return map
  }, [weeklyLogs, daysOfWeek])

  const stats = useMemo(() => {
    const completedTaskIds = new Set<string>()
    const inProgressTaskIds = new Set<string>()

    weeklyLogs.forEach((log) => {
      const task = taskMap.get(log.taskId)
      if (task) {
        if (task.status === 'done' || task.status === 'archived') {
          completedTaskIds.add(task.id)
        } else if (task.status === 'doing') {
          inProgressTaskIds.add(task.id)
        }
      }
    })

    return {
      logCount: weeklyLogs.length,
      completedTasks: completedTaskIds.size,
      inProgressTasks: inProgressTaskIds.size,
    }
  }, [weeklyLogs, taskMap])

  const goToPreviousWeek = () => setCurrentWeekStart((prev) => subWeeks(prev, 1))
  const goToNextWeek = () => setCurrentWeekStart((prev) => addWeeks(prev, 1))
  const goToCurrentWeek = () =>
    setCurrentWeekStart(startOfWeek(new Date(), { weekStartsOn: 1 }))

  const isToday = (day: Date) => isSameDay(day, new Date())

  return (
    <div>
      <div className="bg-[var(--wa-surface)] rounded-sm shadow-sm p-4 mb-6 border border-[var(--wa-border)]">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div className="flex items-center gap-4">
            <button
              onClick={goToPreviousWeek}
              className="p-2 hover:bg-[var(--wa-surface-alt)] rounded-sm transition-colors text-[var(--wa-text-secondary)]"
            >
              ←
            </button>
            <div className="text-center">
              <h2 className="font-semibold text-[var(--wa-text-primary)]">
                {format(currentWeekStart, 'M月d日', { locale: ja })} - {format(weekEnd, 'M月d日', { locale: ja })}
              </h2>
            </div>
            <button
              onClick={goToNextWeek}
              className="p-2 hover:bg-[var(--wa-surface-alt)] rounded-sm transition-colors text-[var(--wa-text-secondary)]"
            >
              →
            </button>
            <button
              onClick={goToCurrentWeek}
              className="text-sm text-[var(--wa-primary)] hover:text-[var(--wa-primary-dark)]"
            >
              今日
            </button>
          </div>
          <div className="flex gap-6 text-sm">
            <div className="text-center">
              <p className="text-2xl font-bold text-[var(--wa-text-primary)]">{stats.logCount}</p>
              <p className="text-[var(--wa-text-muted)]">作業記録</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-[var(--wa-done)]">{stats.completedTasks}</p>
              <p className="text-[var(--wa-text-muted)]">完了</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-[var(--wa-doing)]">{stats.inProgressTasks}</p>
              <p className="text-[var(--wa-text-muted)]">進行中</p>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-7 gap-4">
        {daysOfWeek.map((day) => {
          const dayStr = format(day, 'yyyy-MM-dd')
          const logs = logsByDay.get(dayStr) ?? []
          const dayName = format(day, 'E', { locale: ja })
          const dayNum = format(day, 'd')

          return (
            <div
              key={dayStr}
              className={cn(
                'bg-[var(--wa-surface)] rounded-sm shadow-sm overflow-hidden border border-[var(--wa-border)]',
                isToday(day) && 'ring-2 ring-[var(--wa-primary)]'
              )}
            >
              <div
                className={cn(
                  'px-3 py-2 border-b border-[var(--wa-border)]',
                  isToday(day) ? 'bg-[#e8ebf5]' : 'bg-[var(--wa-surface-alt)]'
                )}
              >
                <p className="text-xs text-[var(--wa-text-muted)]">{dayName}</p>
                <p
                  className={cn(
                    'text-lg font-semibold',
                    isToday(day) ? 'text-[var(--wa-primary)]' : 'text-[var(--wa-text-primary)]'
                  )}
                >
                  {dayNum}
                </p>
              </div>
              <div className="p-2 min-h-[120px] max-h-[200px] overflow-y-auto">
                {logs.length === 0 ? (
                  <p className="text-xs text-[var(--wa-text-muted)] text-center py-4">
                    記録なし
                  </p>
                ) : (
                  <div className="space-y-2">
                    {logs.map((log) => {
                      const task = taskMap.get(log.taskId)
                      return (
                        <div
                          key={log.id}
                          className="p-2 bg-[var(--wa-surface-alt)] rounded-sm text-xs"
                        >
                          <p className="text-[var(--wa-text-primary)] line-clamp-2">
                            {log.content}
                          </p>
                          {task && (
                            <p className="text-[var(--wa-text-muted)] mt-1 truncate">
                              {task.title}
                            </p>
                          )}
                        </div>
                      )
                    })}
                  </div>
                )}
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

'use client'

import { useState, useMemo } from 'react'
import type { Task, WorkLog } from '@/types'
import { formatDate, formatDateTime } from '@/lib/utils'

interface ArchiveViewProps {
  initialTasks: Task[]
  workLogs: WorkLog[]
}

export function ArchiveView({ initialTasks, workLogs }: ArchiveViewProps) {
  const [tasks, setTasks] = useState(initialTasks)
  const [isProcessing, setIsProcessing] = useState<string | null>(null)

  const taskWorkLogs = useMemo(() => {
    const map = new Map<string, WorkLog[]>()
    workLogs.forEach((log) => {
      const existing = map.get(log.taskId) ?? []
      map.set(log.taskId, [...existing, log])
    })
    return map
  }, [workLogs])

  const sortedTasks = useMemo(
    () =>
      [...tasks].sort(
        (a, b) =>
          new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
      ),
    [tasks]
  )

  const handleRestore = async (taskId: string) => {
    setIsProcessing(taskId)
    try {
      const response = await fetch(`/api/tasks/${taskId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'todo' }),
      })

      if (response.ok) {
        setTasks((prev) => prev.filter((t) => t.id !== taskId))
      }
    } finally {
      setIsProcessing(null)
    }
  }

  const handleDelete = async (taskId: string) => {
    if (!confirm('この案件を完全に削除しますか？')) {
      return
    }

    setIsProcessing(taskId)
    try {
      const response = await fetch(`/api/tasks/${taskId}`, {
        method: 'DELETE',
      })

      if (response.ok) {
        setTasks((prev) => prev.filter((t) => t.id !== taskId))
      }
    } finally {
      setIsProcessing(null)
    }
  }

  if (sortedTasks.length === 0) {
    return (
      <div className="bg-[var(--wa-surface)] rounded-sm shadow-sm p-8 text-center border border-[var(--wa-border)]">
        <p className="text-[var(--wa-text-muted)]">保管された案件はありません</p>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {sortedTasks.map((task) => {
        const logs = taskWorkLogs.get(task.id) ?? []
        const isLoading = isProcessing === task.id

        return (
          <div
            key={task.id}
            className="bg-[var(--wa-surface)] rounded-sm shadow-sm overflow-hidden border border-[var(--wa-border)]"
          >
            <div className="p-4 border-b border-[var(--wa-surface-alt)]">
              <div className="flex justify-between items-start">
                <div className="flex-1">
                  <h3 className="font-medium text-[var(--wa-text-primary)]">{task.title}</h3>
                  {task.description && (
                    <p className="text-sm text-[var(--wa-text-secondary)] mt-1">
                      {task.description}
                    </p>
                  )}
                  <div className="flex items-center gap-4 mt-2 text-xs text-[var(--wa-text-muted)]">
                    {task.dueDate && (
                      <span>期限: {formatDate(task.dueDate)}</span>
                    )}
                    <span>保管日: {formatDateTime(task.updatedAt)}</span>
                    <span>{logs.length} 件の作業記録</span>
                  </div>
                </div>
                <div className="flex gap-2 ml-4">
                  <button
                    onClick={() => handleRestore(task.id)}
                    disabled={isLoading}
                    className="px-3 py-1 text-sm bg-[var(--wa-primary)] text-white rounded-sm hover:bg-[var(--wa-primary-dark)] disabled:opacity-50"
                  >
                    復元
                  </button>
                  <button
                    onClick={() => handleDelete(task.id)}
                    disabled={isLoading}
                    className="px-3 py-1 text-sm bg-[var(--wa-secondary)] text-white rounded-sm hover:bg-[var(--wa-secondary-light)] disabled:opacity-50"
                  >
                    削除
                  </button>
                </div>
              </div>
            </div>
            {logs.length > 0 && (
              <div className="px-4 py-3 bg-[var(--wa-surface-alt)]">
                <p className="text-xs text-[var(--wa-text-muted)] mb-2">作業記録:</p>
                <div className="space-y-1 max-h-32 overflow-y-auto">
                  {logs
                    .sort(
                      (a, b) =>
                        new Date(b.createdAt).getTime() -
                        new Date(a.createdAt).getTime()
                    )
                    .slice(0, 5)
                    .map((log) => (
