'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'

export default function LoginPage() {
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const router = useRouter()

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setIsLoading(true)

    try {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password }),
      })

      const data = await response.json()

      if (!response.ok || !data.success) {
        setError(data.error === 'Invalid password' ? '合言葉が違います' : '入場できませんでした')
        return
      }

      router.push('/')
      router.refresh()
    } catch {
      setError('エラーが発生しました。再度お試しください。')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-[var(--wa-background)]">
      <div className="bg-[var(--wa-surface)] p-8 rounded-sm shadow-md w-full max-w-md border-2 border-[var(--wa-border)]">
        <h1 className="text-2xl font-bold text-center mb-6 text-[var(--wa-primary)]">
          帳簿
        </h1>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label
              htmlFor="password"
              className="block text-sm font-medium text-[var(--wa-text-secondary)] mb-1"
            >
              合言葉
            </label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-3 py-2 border border-[var(--wa-border)] rounded-sm focus:outline-none focus:ring-2 focus:ring-[var(--wa-primary-light)] focus:border-transparent bg-[var(--wa-surface)]"
              placeholder="合言葉を入力"
              required
            />
          </div>
          {error && (
            <p className="text-[var(--wa-secondary)] text-sm">{error}</p>
          )}
          <button
            type="submit"
            disabled={isLoading}
            className="w-full bg-[var(--wa-primary)] text-white py-2 px-4 rounded-sm hover:bg-[var(--wa-primary-dark)] focus:outline-none focus:ring-2 focus:ring-[var(--wa-primary-light)] focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {isLoading ? '入場中...' : '入場'}
          </button>
        </form>
      </div>
    </div>
  )
}

