'use client'

import { useState, useMemo } from 'react'
import type { WorkLog, Task } from '@/types'
import { formatDate, formatDateTime } from '@/lib/utils'

interface DailyViewProps {
  workLogs: WorkLog[]
  tasks: Task[]
}

export function DailyView({ workLogs, tasks }: DailyViewProps) {
  const [filterDate, setFilterDate] = useState('')

  const taskMap = useMemo(() => {
    const map = new Map<string, Task>()
    tasks.forEach((task) => map.set(task.id, task))
    return map
  }, [tasks])

  const groupedLogs = useMemo(() => {
    const filtered = filterDate
      ? workLogs.filter((log) => log.date === filterDate)
      : workLogs

    const groups = new Map<string, WorkLog[]>()

    filtered.forEach((log) => {
      const existing = groups.get(log.date) ?? []
      groups.set(log.date, [...existing, log])
    })

    return Array.from(groups.entries())
      .sort(([a], [b]) => b.localeCompare(a))
      .map(([date, logs]) => ({
        date,
        logs: logs.sort(
          (a, b) =>
            new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        ),
      }))
  }, [workLogs, filterDate])

  return (
    <div>
      <div className="mb-6 flex items-center gap-4">
        <label className="text-sm font-medium text-[var(--tw-text-secondary)]">
          Filter by date:
        </label>
        <input
          type="date"
          value={filterDate}
          onChange={(e) => setFilterDate(e.target.value)}
          className="px-3 py-2 border border-[var(--tw-border)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--tw-primary)] bg-[var(--tw-surface)]"
        />
        {filterDate && (
          <button
            onClick={() => setFilterDate('')}
            className="text-sm text-[var(--tw-text-muted)] hover:text-[var(--tw-text-primary)]"
          >
            Clear filter
          </button>
        )}
      </div>

      {groupedLogs.length === 0 ? (
        <div className="bg-[var(--tw-surface)] rounded-lg shadow-sm p-8 text-center border border-[var(--tw-border)]">
          <p className="text-[var(--tw-text-muted)]">No work logs found</p>
        </div>
      ) : (
        <div className="space-y-6">
          {groupedLogs.map(({ date, logs }) => (
            <div key={date} className="bg-[var(--tw-surface)] rounded-lg shadow-sm overflow-hidden border border-[var(--tw-border)]">
              <div className="bg-[var(--tw-surface-alt)] px-6 py-3 border-b border-[var(--tw-border)]">
                <h2 className="font-semibold text-[var(--tw-text-primary)]">
                  {formatDate(date)}
                </h2>
                <p className="text-sm text-[var(--tw-text-muted)]">{logs.length} entries</p>
              </div>
              <div className="divide-y divide-[var(--tw-surface-alt)]">
                {logs.map((log) => {
                  const task = taskMap.get(log.taskId)
                  return (
                    <div key={log.id} className="px-6 py-4">
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <p className="text-[var(--tw-text-primary)]">{log.content}</p>
                          <div className="mt-1 flex items-center gap-2 text-sm text-[var(--tw-text-muted)]">
                            {task && (
                              <>
                                <span className="inline-flex items-center px-2 py-0.5 rounded-lg text-xs font-medium bg-[var(--tw-surface-alt)] text-[var(--tw-text-secondary)]">
                                  {task.title}
                                </span>
                                {task.status === 'archived' && (
                                  <span className="text-xs text-[var(--tw-text-muted)]">
                                    (Archived)
                                  </span>
                                )}
                              </>
                            )}
                          </div>
                        </div>
                        <span className="text-xs text-[var(--tw-text-muted)] ml-4 whitespace-nowrap">
                          {formatDateTime(log.createdAt)}
                        </span>
                      </div>
                    </div>
                  )
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

