'use client'

import { useState, useMemo } from 'react'
import {
  startOfWeek,
  endOfWeek,
  addWeeks,
  subWeeks,
  format,
  eachDayOfInterval,
  isSameDay,
  parseISO,
} from 'date-fns'
import { ja } from 'date-fns/locale'
import type { WorkLog, Task } from '@/types'
import { cn } from '@/lib/utils'

interface WeeklyViewProps {
  workLogs: WorkLog[]
  tasks: Task[]
}

export function WeeklyView({ workLogs, tasks }: WeeklyViewProps) {
  const [currentWeekStart, setCurrentWeekStart] = useState(() =>
    startOfWeek(new Date(), { weekStartsOn: 1 })
  )

  const weekEnd = endOfWeek(currentWeekStart, { weekStartsOn: 1 })

  const daysOfWeek = useMemo(
    () => eachDayOfInterval({ start: currentWeekStart, end: weekEnd }),
    [currentWeekStart, weekEnd]
  )

  const taskMap = useMemo(() => {
    const map = new Map<string, Task>()
    tasks.forEach((task) => map.set(task.id, task))
    return map
  }, [tasks])

  const weeklyLogs = useMemo(() => {
    return workLogs.filter((log) => {
      const logDate = parseISO(log.date)
      return logDate >= currentWeekStart && logDate <= weekEnd
    })
  }, [workLogs, currentWeekStart, weekEnd])

  const logsByDay = useMemo(() => {
    const map = new Map<string, WorkLog[]>()
    daysOfWeek.forEach((day) => {
      const dayStr = format(day, 'yyyy-MM-dd')
      map.set(dayStr, [])
    })
    weeklyLogs.forEach((log) => {
      const existing = map.get(log.date) ?? []
      map.set(log.date, [...existing, log])
    })
    return map
  }, [weeklyLogs, daysOfWeek])

  const stats = useMemo(() => {
    const completedTaskIds = new Set<string>()
    const inProgressTaskIds = new Set<string>()

    weeklyLogs.forEach((log) => {
      const task = taskMap.get(log.taskId)
      if (task) {
        if (task.status === 'done' || task.status === 'archived') {
          completedTaskIds.add(task.id)
        } else if (task.status === 'doing') {
          inProgressTaskIds.add(task.id)
        }
      }
    })

    return {
      logCount: weeklyLogs.length,
      completedTasks: completedTaskIds.size,
      inProgressTasks: inProgressTaskIds.size,
    }
  }, [weeklyLogs, taskMap])

  const goToPreviousWeek = () => setCurrentWeekStart((prev) => subWeeks(prev, 1))
  const goToNextWeek = () => setCurrentWeekStart((prev) => addWeeks(prev, 1))
  const goToCurrentWeek = () =>
    setCurrentWeekStart(startOfWeek(new Date(), { weekStartsOn: 1 }))

  const isToday = (day: Date) => isSameDay(day, new Date())

  return (
    <div>
      <div className="bg-[var(--wa-surface)] rounded-sm shadow-sm p-4 mb-6 border border-[var(--wa-border)]">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div className="flex items-center gap-4">
            <button
              onClick={goToPreviousWeek}
              className="p-2 hover:bg-[var(--wa-surface-alt)] rounded-sm transition-colors text-[var(--wa-text-secondary)]"
            >
              ←
            </button>
            <div className="text-center">
              <h2 className="font-semibold text-[var(--wa-text-primary)]">
                {format(currentWeekStart, 'M月d日', { locale: ja })} - {format(weekEnd, 'M月d日', { locale: ja })}
              </h2>
            </div>
            <button
              onClick={goToNextWeek}
              className="p-2 hover:bg-[var(--wa-surface-alt)] rounded-sm transition-colors text-[var(--wa-text-secondary)]"
            >
              →
            </button>
            <button
              onClick={goToCurrentWeek}
              className="text-sm text-[var(--wa-primary)] hover:text-[var(--wa-primary-dark)]"
            >
              今日
            </button>
          </div>
          <div className="flex gap-6 text-sm">
            <div className="text-center">
              <p className="text-2xl font-bold text-[var(--wa-text-primary)]">{stats.logCount}</p>
              <p className="text-[var(--wa-text-muted)]">作業記録</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-[var(--wa-done)]">{stats.completedTasks}</p>
              <p className="text-[var(--wa-text-muted)]">完了</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-[var(--wa-doing)]">{stats.inProgressTasks}</p>
              <p className="text-[var(--wa-text-muted)]">進行中</p>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-7 gap-4">
        {daysOfWeek.map((day) => {
          const dayStr = format(day, 'yyyy-MM-dd')
          const logs = logsByDay.get(dayStr) ?? []
          const dayName = format(day, 'E', { locale: ja })
          const dayNum = format(day, 'd')

          return (
            <div
              key={dayStr}
              className={cn(
                'bg-[var(--wa-surface)] rounded-sm shadow-sm overflow-hidden border border-[var(--wa-border)]',
                isToday(day) && 'ring-2 ring-[var(--wa-primary)]'
              )}
            >
              <div
                className={cn(
                  'px-3 py-2 border-b border-[var(--wa-border)]',
                  isToday(day) ? 'bg-[#e8ebf5]' : 'bg-[var(--wa-surface-alt)]'
                )}
              >
                <p className="text-xs text-[var(--wa-text-muted)]">{dayName}</p>
                <p
                  className={cn(
                    'text-lg font-semibold',
                    isToday(day) ? 'text-[var(--wa-primary)]' : 'text-[var(--wa-text-primary)]'
                  )}
                >
                  {dayNum}
                </p>
              </div>
              <div className="p-2 min-h-[120px] max-h-[200px] overflow-y-auto">
                {logs.length === 0 ? (
                  <p className="text-xs text-[var(--wa-text-muted)] text-center py-4">
                    記録なし
                  </p>
                ) : (
                  <div className="space-y-2">
                    {logs.map((log) => {
                      const task = taskMap.get(log.taskId)
                      return (
                        <div
                          key={log.id}
                          className="p-2 bg-[var(--wa-surface-alt)] rounded-sm text-xs"
                        >
                          <p className="text-[var(--wa-text-primary)] line-clamp-2">
                            {log.content}
                          </p>
                          {task && (
                            <p className="text-[var(--wa-text-muted)] mt-1 truncate">
                              {task.title}
                            </p>
                          )}
                        </div>
                      )
                    })}
                  </div>
                )}
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

