import type { Task, WorkLog } from '@/types'
import { formatDate, formatDateTime } from '@/lib/utils'

interface ArchiveViewProps {
  initialTasks: Task[]
  workLogs: WorkLog[]
}

export function ArchiveView({ initialTasks, workLogs }: ArchiveViewProps) {
  const [tasks, setTasks] = useState(initialTasks)
  const [isProcessing, setIsProcessing] = useState<string | null>(null)

  const taskWorkLogs = useMemo(() => {
    const map = new Map<string, WorkLog[]>()
    workLogs.forEach((log) => {
      const existing = map.get(log.taskId) ?? []
      map.set(log.taskId, [...existing, log])
    })
    return map
  }, [workLogs])

  const sortedTasks = useMemo(
    () =>
      [...tasks].sort(
        (a, b) =>
          new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
      ),
    [tasks]
  )

  const handleRestore = async (taskId: string) => {
    setIsProcessing(taskId)
    try {
      const response = await fetch(`/api/tasks/${taskId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'todo' }),
      })

      if (response.ok) {
        setTasks((prev) => prev.filter((t) => t.id !== taskId))
      }
    } finally {
      setIsProcessing(null)
    }
  }

  const handleDelete = async (taskId: string) => {
    if (!confirm('Are you sure you want to permanently delete this task?')) {
      return
    }

    setIsProcessing(taskId)
    try {
      const response = await fetch(`/api/tasks/${taskId}`, {
        method: 'DELETE',
      })

      if (response.ok) {
        setTasks((prev) => prev.filter((t) => t.id !== taskId))
      }
    } finally {
      setIsProcessing(null)
    }
  }

  if (sortedTasks.length === 0) {
    return (
      <div className="bg-[var(--tw-surface)] rounded-lg shadow-sm p-8 text-center border border-[var(--tw-border)]">
        <p className="text-[var(--tw-text-muted)]">No archived tasks</p>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {sortedTasks.map((task) => {
        const logs = taskWorkLogs.get(task.id) ?? []
        const isLoading = isProcessing === task.id

        return (
          <div
            key={task.id}
            className="bg-[var(--tw-surface)] rounded-lg shadow-sm overflow-hidden border border-[var(--tw-border)]"
          >
            <div className="p-4 border-b border-[var(--tw-surface-alt)]">
              <div className="flex justify-between items-start">
                <div className="flex-1">
                  <h3 className="font-medium text-[var(--tw-text-primary)]">{task.title}</h3>
                  {task.description && (
                    <p className="text-sm text-[var(--tw-text-secondary)] mt-1">
                      {task.description}
                    </p>
                  )}
                  <div className="flex items-center gap-4 mt-2 text-xs text-[var(--tw-text-muted)]">
                    {task.dueDate && (
                      <span>Due: {formatDate(task.dueDate)}</span>
                    )}
                    <span>Archived: {formatDateTime(task.updatedAt)}</span>
                    <span>{logs.length} work logs</span>
                  </div>
                </div>
                <div className="flex gap-2 ml-4">
                  <button
                    onClick={() => handleRestore(task.id)}
                    disabled={isLoading}
                    className="px-3 py-1 text-sm bg-[var(--tw-doing)] text-white rounded-lg hover:opacity-90 disabled:opacity-50"
                  >
                    Restore
                  </button>
                  <button
                    onClick={() => handleDelete(task.id)}
                    disabled={isLoading}
                    className="px-3 py-1 text-sm bg-[var(--tw-primary)] text-white rounded-lg hover:bg-[var(--tw-primary-dark)] disabled:opacity-50"
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
            {logs.length > 0 && (
              <div className="px-4 py-3 bg-[var(--tw-surface-alt)]">
                <p className="text-xs text-[var(--tw-text-muted)] mb-2">Work logs:</p>
                <div className="space-y-1 max-h-32 overflow-y-auto">
                  {logs
                    .sort(
                      (a, b) =>
                        new Date(b.createdAt).getTime() -
                        new Date(a.createdAt).getTime()
                    )
                    .slice(0, 5)
                    .map((log) => (
                      <div key={log.id} className="text-xs text-[var(--tw-text-secondary)]">
                        <span className="text-[var(--tw-text-muted)] mr-2">
                          {formatDate(log.date)}
                        </span>
                        {log.content}
                      </div>
                    ))}
                  {logs.length > 5 && (
                    <p className="text-xs text-[var(--tw-text-muted)]">
                      +{logs.length - 5} more
                    </p>
                  )}
                </div>
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}

