                  )}
                  <div className="flex items-center gap-4 mt-2 text-xs text-[var(--wa-text-muted)]">
                    {task.dueDate && (
                      <span>期限: {formatDate(task.dueDate)}</span>
                    )}
                    <span>保管日: {formatDateTime(task.updatedAt)}</span>
                    <span>{logs.length} 件の作業記録</span>
                  </div>
                </div>
                <div className="flex gap-2 ml-4">
                  <button
                    onClick={() => handleRestore(task.id)}
                    disabled={isLoading}
                    className="px-3 py-1 text-sm bg-[var(--wa-primary)] text-white rounded-sm hover:bg-[var(--wa-primary-dark)] disabled:opacity-50"
                  >
                    復元
                  </button>
                  <button
                    onClick={() => handleDelete(task.id)}
                    disabled={isLoading}
                    className="px-3 py-1 text-sm bg-[var(--wa-secondary)] text-white rounded-sm hover:bg-[var(--wa-secondary-light)] disabled:opacity-50"
                  >
                    削除
                  </button>
                </div>
              </div>
            </div>
            {logs.length > 0 && (
              <div className="px-4 py-3 bg-[var(--wa-surface-alt)]">
                <p className="text-xs text-[var(--wa-text-muted)] mb-2">作業記録:</p>
                <div className="space-y-1 max-h-32 overflow-y-auto">
                  {logs
                    .sort(
                      (a, b) =>
                        new Date(b.createdAt).getTime() -
                        new Date(a.createdAt).getTime()
                    )
                    .slice(0, 5)
                    .map((log) => (
                      <div key={log.id} className="text-xs text-[var(--wa-text-secondary)]">
                        <span className="text-[var(--wa-text-muted)] mr-2">
                          {formatDate(log.date)}
                        </span>
                        {log.content}
                      </div>
                    ))}
                  {logs.length > 5 && (
                    <p className="text-xs text-[var(--wa-text-muted)]">
                      他 {logs.length - 5} 件
                    </p>
                  )}
                </div>
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}

