'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'

export default function LoginPage() {
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const router = useRouter()

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setIsLoading(true)

    try {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password }),
      })

      const data = await response.json()

      if (!response.ok || !data.success) {
        setError(data.error === 'Invalid password' ? 'Invalid password' : 'Login failed')
        return
      }

      router.push('/')
      router.refresh()
    } catch {
      setError('An error occurred. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-[var(--tw-background)]">
      <div className="bg-[var(--tw-surface)] p-8 rounded-xl shadow-lg w-full max-w-md border border-[var(--tw-border)]">
        <h1 className="text-2xl font-bold text-center mb-6 text-[var(--tw-primary)]">
          Task Board
        </h1>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label
              htmlFor="password"
              className="block text-sm font-medium text-[var(--tw-text-secondary)] mb-1"
            >
              Password
            </label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-3 py-2 border border-[var(--tw-border)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--tw-primary)] focus:border-transparent bg-[var(--tw-surface)]"
              placeholder="Enter password"
              required
            />
          </div>
          {error && (
            <p className="text-[var(--tw-primary)] text-sm">{error}</p>
          )}
          <button
            type="submit"
            disabled={isLoading}
            className="w-full bg-[var(--tw-primary)] text-white py-2 px-4 rounded-lg hover:bg-[var(--tw-primary-dark)] focus:outline-none focus:ring-2 focus:ring-[var(--tw-primary)] focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {isLoading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>
      </div>
    </div>
  )
}

