import { redirect } from 'next/navigation'
import { isAuthenticated } from '@/lib/auth'
import { getTasks, getWorkLogs } from '@/lib/kv'
import { KanbanBoard } from '@/components/KanbanBoard'
import { Header } from '@/components/Header'

export const dynamic = 'force-dynamic'

export default async function HomePage() {
  const authenticated = await isAuthenticated()

  if (!authenticated) {
    redirect('/login')
  }

  const [tasks, workLogs] = await Promise.all([
    getTasks(),
    getWorkLogs(),
  ])

  return (
    <div className="min-h-screen bg-[var(--wa-background)]">
      <Header />
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        <h1 className="text-2xl font-bold text-[var(--wa-text-primary)] mb-6">看板</h1>
        <KanbanBoard initialTasks={tasks} initialWorkLogs={workLogs} />
      </main>
    </div>
  )
}

