@import "tailwindcss";

:root {
  /* === Twilio Brand Color Palette === */

  /* Base colors */
  --tw-background: #f4f4f6;        /* Light gray background */
  --tw-foreground: #121c2d;        /* Dark navy text */

  /* Primary (Twilio Red) */
  --tw-primary: #f22f46;           /* Twilio Red */
  --tw-primary-light: #ff6b7a;     /* Light red */
  --tw-primary-dark: #c91f33;      /* Dark red */

  /* Secondary (Navy) */
  --tw-secondary: #0d122b;         /* Twilio Navy */
  --tw-secondary-light: #233659;   /* Light navy */

  /* Status colors */
  --tw-todo: #606b85;              /* Gray blue - Todo */
  --tw-doing: #0263e0;             /* Blue - Doing */
  --tw-done: #14b053;              /* Green - Done */
  --tw-archived: #8891aa;          /* Gray - Archived */

  /* Surface colors */
  --tw-surface: #ffffff;           /* White - Card background */
  --tw-surface-alt: #eaebf0;       /* Light gray - Alt background */
  --tw-border: #c9ccd8;            /* Border color */
  --tw-border-dark: #8891aa;       /* Dark border */

  /* Text colors */
  --tw-text-primary: #121c2d;      /* Primary text */
  --tw-text-secondary: #394762;    /* Secondary text */
  --tw-text-muted: #606b85;        /* Muted text */

  /* Status backgrounds */
  --tw-todo-bg: #f0f1f5;           /* Todo background */
  --tw-doing-bg: #e6f0fc;          /* Doing background */
  --tw-done-bg: #e6f7ed;           /* Done background */

  /* Legacy compatibility */
  --background: var(--tw-background);
  --foreground: var(--tw-foreground);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
}

body {
  background: var(--tw-background);
  color: var(--tw-text-primary);
}

.kanban-column {
  min-height: 400px;
}

.task-card {
  cursor: grab;
  border-radius: 8px;
}

.task-card:active {
  cursor: grabbing;
}

.task-card-dragging {
  opacity: 0.5;
  transform: rotate(2deg);
}

.drop-indicator {
  height: 2px;
  background-color: var(--tw-primary);
  margin: 4px 0;
}

/* Focus styles */
input:focus,
textarea:focus,
button:focus-visible {
  outline: 2px solid var(--tw-primary);
  outline-offset: 2px;
}

/* Scrollbar styles */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--tw-surface-alt);
}

::-webkit-scrollbar-thumb {
  background: var(--tw-border-dark);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--tw-text-secondary);
}

