'use client'

import Link from 'next/link'
import { usePathname, useRouter } from 'next/navigation'
import { cn } from '@/lib/utils'

const navItems = [
  { href: '/', label: 'Board' },
  { href: '/daily', label: 'Daily' },
  { href: '/weekly', label: 'Weekly' },
  { href: '/archive', label: 'Archive' },
]

export function Header() {
  const pathname = usePathname()
  const router = useRouter()

  const handleLogout = async () => {
    try {
      await fetch('/api/auth/logout', { method: 'POST' })
      router.push('/login')
      router.refresh()
    } catch {
      // Ignore logout errors
    }
  }

  return (
    <header className="bg-[var(--tw-surface)] shadow-sm border-b border-[var(--tw-border)]">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          <div className="flex items-center space-x-8">
            <h1 className="text-xl font-bold text-[var(--tw-primary)]">Task Board</h1>
            <nav className="hidden md:flex space-x-1">
              {navItems.map((item) => (
                <Link
                  key={item.href}
                  href={item.href}
                  className={cn(
                    'px-4 py-2 rounded-lg text-sm font-medium transition-colors',
                    pathname === item.href
                      ? 'bg-[var(--tw-primary)] text-white'
                      : 'text-[var(--tw-text-secondary)] hover:text-[var(--tw-text-primary)] hover:bg-[var(--tw-surface-alt)]'
                  )}
                >
                  {item.label}
                </Link>
              ))}
            </nav>
          </div>
          <button
            onClick={handleLogout}
            className="text-sm text-[var(--tw-text-secondary)] hover:text-[var(--tw-primary)] transition-colors font-medium"
          >
            Logout
          </button>
        </div>
        <nav className="md:hidden pb-3 flex space-x-2 overflow-x-auto">
          {navItems.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              className={cn(
                'px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-colors',
                pathname === item.href
                  ? 'bg-[var(--tw-primary)] text-white'
                  : 'text-[var(--tw-text-secondary)] hover:text-[var(--tw-text-primary)] hover:bg-[var(--tw-surface-alt)]'
              )}
            >
              {item.label}
            </Link>
          ))}
        </nav>
      </div>
    </header>
  )
}

