            <div className="text-center">
              <p className="text-2xl font-bold text-[var(--tw-done)]">{stats.completedTasks}</p>
              <p className="text-[var(--tw-text-muted)]">Done</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-[var(--tw-doing)]">{stats.inProgressTasks}</p>
              <p className="text-[var(--tw-text-muted)]">In Progress</p>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-7 gap-4">
        {daysOfWeek.map((day) => {
          const dayStr = format(day, 'yyyy-MM-dd')
          const logs = logsByDay.get(dayStr) ?? []
          const dayName = format(day, 'EEE')
          const dayNum = format(day, 'd')

          return (
            <div
              key={dayStr}
              className={cn(
                'bg-[var(--tw-surface)] rounded-lg shadow-sm overflow-hidden border border-[var(--tw-border)]',
                isToday(day) && 'ring-2 ring-[var(--tw-primary)]'
              )}
            >
              <div
                className={cn(
                  'px-3 py-2 border-b border-[var(--tw-border)]',
                  isToday(day) ? 'bg-red-50' : 'bg-[var(--tw-surface-alt)]'
                )}
              >
                <p className="text-xs text-[var(--tw-text-muted)]">{dayName}</p>
                <p
                  className={cn(
                    'text-lg font-semibold',
                    isToday(day) ? 'text-[var(--tw-primary)]' : 'text-[var(--tw-text-primary)]'
                  )}
                >
                  {dayNum}
                </p>
              </div>
              <div className="p-2 min-h-[120px] max-h-[200px] overflow-y-auto">
                {logs.length === 0 ? (
                  <p className="text-xs text-[var(--tw-text-muted)] text-center py-4">
                    No logs
                  </p>
                ) : (
                  <div className="space-y-2">
                    {logs.map((log) => {
                      const task = taskMap.get(log.taskId)
                      return (
                        <div
                          key={log.id}
                          className="p-2 bg-[var(--tw-surface-alt)] rounded-lg text-xs"
                        >
                          <p className="text-[var(--tw-text-primary)] line-clamp-2">
                            {log.content}
                          </p>
                          {task && (
                            <p className="text-[var(--tw-text-muted)] mt-1 truncate">
                              {task.title}
                            </p>
                          )}
                        </div>
                      )
                    })}
                  </div>
                )}
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}
